// 由 D:/document/念佛板块/text/renwang/lines.noquote.json 生成（scripts/import-nianjing-new.mjs），不要手改
export default {
 "slug": "renwang",
 "title": "仁王护国经",
 "fullTitle": "仁王护国般若波罗蜜多经",
 "translator": "唐 大广智不空 奉诏译",
 "source": {
  "name": "CBETA 线上阅读",
  "id": "T08n0246",
  "url": "https://cbetaonline.dila.edu.tw/zh/T08n0246_p0834a"
 },
 "license": "CBETA 电子佛典，CC BY-NC-SA 3.0 TW",
 "charCount": 13368,
 "lines": [
  {
   "n": 1,
   "text": "如是我闻：",
   "pinyin": "rú shì wǒ wén",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 2,
   "text": "一时，佛住王舍城鹫峰山中，与大比丘众千八百人俱——皆阿罗汉，",
   "pinyin": "yī shí fó zhù wáng shè chéng jiù fēng shān zhōng yǔ dà bǐ qiū zhòng qiān bā bǎi rén jù jiē ā luó hàn",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 3,
   "text": "诸漏已尽无复烦恼，心善解脱、慧善解脱，九智十智所作已办，",
   "pinyin": "zhū lòu yǐ jìn wú fù fán nǎo xīn shàn jiě tuō huì shàn jiě tuō jiǔ zhì shí zhì suǒ zuò yǐ bàn",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 4,
   "text": "三假实观三空门观，有为功德、无为功德皆悉成就；",
   "pinyin": "sān jiǎ shí guān sān kōng mén guān yǒu wéi gōng dé wú wéi gōng dé jiē xī chéng jiù",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 5,
   "text": "复有比丘尼众八百人俱，皆阿罗汉；",
   "pinyin": "fù yǒu bǐ qiū ní zhòng bā bǎi rén jù jiē ā luó hàn",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 6,
   "text": "复有无量无数菩萨摩诃萨——实智平等永断惑障，",
   "pinyin": "fù yǒu wú liàng wú shù pú sà mó hē sà shí zhì píng děng yǒng duàn huò zhàng",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 7,
   "text": "方便善巧起大行愿，以四摄法饶益有情，四无量心普覆一切，",
   "pinyin": "fāng biàn shàn qiǎo qǐ dà xíng yuàn yǐ sì shè fǎ ráo yì yǒu qíng sì wú liàng xīn pǔ fù yí qiè",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 8,
   "text": "三明鉴达得五神通，修习无边菩提分法，工巧技艺超诸世间，",
   "pinyin": "sān míng jiàn dá dé wǔ shén tōng xiū xí wú biān pú tí fēn fǎ gōng qiǎo jì yì chāo zhū shì jiān",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 9,
   "text": "深入缘生，空、无相愿，出入灭定示现难量，摧伏魔怨双照二谛，",
   "pinyin": "shēn rù yuán shēng kōng wú xiàng yuàn chū rù miè dìng shì xiàn nán liàng cuī fú mó yuàn shuāng zhào èr dì",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 10,
   "text": "法眼普见知众生根，四无碍解演说无畏，十力妙智雷震法音，",
   "pinyin": "fǎ yǎn pǔ jiàn zhī zhòng shēng gēn sì wú ài jiě yǎn shuō wú wèi shí lì miào zhì léi zhèn fǎ yīn",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 11,
   "text": "近无等等金刚三昧，如是功德皆悉具足；",
   "pinyin": "jìn wú děng děng jīn gāng sān mèi rú shì gōng dé jiē xī jù zú",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 12,
   "text": "复有无量优婆塞众、优婆夷众，皆见圣谛；",
   "pinyin": "fù yǒu wú liàng yōu pó sāi zhòng yōu pó yí zhòng jiē jiàn shèng dì",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 13,
   "text": "复有无量修七贤行、念处、正勤、神足、根、力，八胜处、十遍处，十六心行趣谛现观；",
   "pinyin": "fù yǒu wú liàng xiū qī xián xíng niàn chù zhèng qín shén zú gēn lì bā shèng chù shí biàn chù shí liù xīn xíng qù dì xiàn guān",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 14,
   "text": "复有十六大国王——波斯匿王等，各与若干千万眷属俱；",
   "pinyin": "fù yǒu shí liù dà guó wáng bō sī nì wáng děng gè yǔ ruò gān qiān wàn juàn shǔ jù",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 15,
   "text": "复有六欲天王——释提桓因等，与其眷属无量天子俱；",
   "pinyin": "fù yǒu liù yù tiān wáng shì tí huán yīn děng yǔ qí juàn shǔ wú liàng tiān zǐ jù",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 16,
   "text": "色四静虑诸大梵王，亦与眷属无量天子俱；",
   "pinyin": "sè sì jìng lǜ zhū dà fàn wáng yì yǔ juàn shǔ wú liàng tiān zǐ jù",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 17,
   "text": "诸趣变化无量有情——阿修罗等，若干眷属俱。",
   "pinyin": "zhū qù biàn huà wú liàng yǒu qíng ā xiū luó děng ruò gān juàn shǔ jù",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 18,
   "text": "复有变现十方净土，而现百亿师子之座，佛坐其上广宣法要。",
   "pinyin": "fù yǒu biàn xiàn shí fāng jìng tǔ ér xiàn bǎi yì shī zǐ zhī zuò fó zuò qí shàng guǎng xuān fǎ yào",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 19,
   "text": "一一座前各现一花，是百亿花众宝严饰。",
   "pinyin": "yī yī zuò qián gè xiàn yī huā shì bǎi yì huā zhòng bǎo yán shì",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 20,
   "text": "于诸花上，一一复有无量化佛、无量菩萨，四众八部悉皆无量。",
   "pinyin": "yú zhū huā shàng yī yī fù yǒu wú liàng huà fó wú liàng pú sà sì zhòng bā bù xī jiē wú liàng",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 21,
   "text": "其中诸佛各各宣说般若波罗蜜多，展转流遍十方恒沙诸佛国土。",
   "pinyin": "qí zhōng zhū fó gè gè xuān shuō bō rě bō luó mì duō zhǎn zhuǎn liú biàn shí fāng héng shā zhū fó guó tǔ",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 22,
   "text": "有如是等诸来大众，各礼佛足退坐一面。",
   "pinyin": "yǒu rú shì děng zhū lái dà zhòng gè lǐ fó zú tuì zuò yī miàn",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 23,
   "text": "尔时世尊，初年月八日，入大寂静妙三摩地，",
   "pinyin": "ěr shí shì zūn chū nián yuè bā rì rù dà jì jìng miào sān mó dì",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 24,
   "text": "身诸毛孔放大光明，普照十方恒沙佛土。",
   "pinyin": "shēn zhū máo kǒng fàng dà guāng míng pǔ zhào shí fāng héng shā fó tǔ",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 25,
   "text": "是时，欲界无量诸天雨众妙花，色界诸天亦雨天花，众色间错甚可爱乐。",
   "pinyin": "shì shí yù jiè wú liàng zhū tiān yǔ zhòng miào huā sè jiè zhū tiān yì yǔ tiān huā zhòng sè jiàn cuò shèn kě ài lè",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 26,
   "text": "时无色界雨诸香花，香如须弥、华如车轮，",
   "pinyin": "shí wú sè jiè yǔ zhū xiāng huā xiāng rú xū mí huá rú chē lún",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 27,
   "text": "如云而下遍覆大众，普佛世界六种震动。",
   "pinyin": "rú yún ér xià biàn fù dà zhòng pǔ fó shì jiè liù zhǒng zhèn dòng",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 28,
   "text": "尔时大众自相谓言：",
   "pinyin": "ěr shí dà zhòng zì xiāng wèi yán",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 29,
   "text": "大觉世尊前已为我等，",
   "pinyin": "dà jué shì zūn qián yǐ wèi wǒ děng",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 30,
   "text": "说摩诃般若波罗蜜多、金刚般若波罗蜜多、天王问般若波罗蜜多、大品等，",
   "pinyin": "shuō mó hē bō rě bō luó mì duō jīn gāng bō rě bō luó mì duō tiān wáng wèn bō rě bō luó mì duō dà pǐn děng",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 31,
   "text": "无量无数般若波罗蜜多。",
   "pinyin": "wú liàng wú shù bō rě bō luó mì duō",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 32,
   "text": "今日如来放大光明，斯作何事？",
   "pinyin": "jīn rì rú lái fàng dà guāng míng sī zuò hé shì",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 33,
   "text": "时室罗筏国波斯匿王作是思惟：",
   "pinyin": "shí shì luó fá guó bō sī nì wáng zuò shì sī wéi",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 34,
   "text": "今佛现是希有之相，必雨法雨，普皆利乐。",
   "pinyin": "jīn fó xiàn shì xī yǒu zhī xiàng bì yǔ fǎ yǔ pǔ jiē lì lè",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 35,
   "text": "即问宝盖、无垢称等诸优婆塞，舍利弗、须菩提等诸大声闻，",
   "pinyin": "jí wèn bǎo gài wú gòu chēng děng zhū yōu pó sāi shè lì fú xū pú tí děng zhū dà shēng wén",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 36,
   "text": "弥勒、师子吼等诸菩萨摩诃萨言：",
   "pinyin": "mí lè shī zǐ hǒu děng zhū pú sà mó hē sà yán",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 37,
   "text": "如来所现，是何瑞相？",
   "pinyin": "rú lái suǒ xiàn shì hé ruì xiàng",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 38,
   "text": "时诸大众无能答者。",
   "pinyin": "shí zhū dà zhòng wú néng dá zhě",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 39,
   "text": "波斯匿王等，承佛神力广作音乐，",
   "pinyin": "bō sī nì wáng děng chéng fó shén lì guǎng zuò yīn yuè",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 40,
   "text": "欲、色诸天各奏无量天诸伎乐，声遍三千大千世界。",
   "pinyin": "yù sè zhū tiān gè zòu wú liàng tiān zhū jì yuè shēng biàn sān qiān dà qiān shì jiè",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 41,
   "text": "尔时，世尊复放无量阿僧祇光，其明杂色，一一光中现宝莲华，",
   "pinyin": "ěr shí shì zūn fù fàng wú liàng ā sēng qí guāng qí míng zá sè yī yī guāng zhōng xiàn bǎo lián huá",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 42,
   "text": "其华千叶皆作金色，上有化佛宣说法要。",
   "pinyin": "qí huá qiān yè jiē zuò jīn sè shàng yǒu huà fó xuān shuō fǎ yào",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 43,
   "text": "是佛光明普于十方恒河沙等诸佛国土，有缘斯现。",
   "pinyin": "shì fó guāng míng pǔ yú shí fāng héng hé shā děng zhū fó guó tǔ yǒu yuán sī xiàn",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 44,
   "text": "彼他方佛国中，",
   "pinyin": "bǐ tā fāng fó guó zhōng",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 45,
   "text": "东方普光菩萨摩诃萨、东南方莲华手菩萨摩诃萨、",
   "pinyin": "dōng fāng pǔ guāng pú sà mó hē sà dōng nán fāng lián huá shǒu pú sà mó hē sà",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 46,
   "text": "南方离忧菩萨摩诃萨、西南方光明菩萨摩诃萨、西方行慧菩萨摩诃萨、",
   "pinyin": "nán fāng lí yōu pú sà mó hē sà xī nán fāng guāng míng pú sà mó hē sà xī fāng xíng huì pú sà mó hē sà",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 47,
   "text": "西北方宝胜菩萨摩诃萨、北方胜受菩萨摩诃萨、东北方离尘菩萨摩诃萨、",
   "pinyin": "xī běi fāng bǎo shèng pú sà mó hē sà běi fāng shèng shòu pú sà mó hē sà dōng běi fāng lí chén pú sà mó hē sà",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 48,
   "text": "上方喜受菩萨摩诃萨、下方莲华胜菩萨摩诃萨，",
   "pinyin": "shàng fāng xǐ shòu pú sà mó hē sà xià fāng lián huá shèng pú sà mó hē sà",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 49,
   "text": "各与无量百千俱胝菩萨摩诃萨皆来至此，持种种香、散种种华，",
   "pinyin": "gè yǔ wú liàng bǎi qiān jù zhī pú sà mó hē sà jiē lái zhì cǐ chí zhǒng zhǒng xiāng sàn zhǒng zhǒng huá",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 50,
   "text": "作无量音乐供养如来，顶礼佛足，默然退坐，合掌恭敬，一心观佛。",
   "pinyin": "zuò wú liàng yīn yuè gòng yǎng rú lái dǐng lǐ fó zú mò rán tuì zuò hé zhǎng gōng jìng yī xīn guān fó",
   "part": "长行",
   "heading": "卷上　序品第一"
  },
  {
   "n": 51,
   "text": "尔时世尊从三昧起，坐师子座，告大众言：",
   "pinyin": "ěr shí shì zūn cóng sān mèi qǐ zuò shī zǐ zuò gào dà zhòng yán",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 52,
   "text": "吾知十六诸国王等咸作是念：",
   "pinyin": "wú zhī shí liù zhū guó wáng děng xián zuò shì niàn",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 53,
   "text": "世尊大慈，普皆利乐。",
   "pinyin": "shì zūn dà cí pǔ jiē lì lè",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 54,
   "text": "我等诸王，云何护国？",
   "pinyin": "wǒ děng zhū wáng yún hé hù guó",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 55,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 56,
   "text": "吾今先为诸菩萨摩诃萨，说护佛果、护十地行。",
   "pinyin": "wú jīn xiān wèi zhū pú sà mó hē sà shuō hù fó guǒ hù shí dì xíng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 57,
   "text": "汝等皆应谛听谛听，善思念之。",
   "pinyin": "rǔ děng jiē yīng dì tīng dì tīng shàn sī niàn zhī",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 58,
   "text": "是时大众——波斯匿王等，闻佛语已，咸共赞言：",
   "pinyin": "shì shí dà zhòng bō sī nì wáng děng wén fó yǔ yǐ xián gòng zàn yán",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 59,
   "text": "善哉，善哉！",
   "pinyin": "shàn zāi shàn zāi",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 60,
   "text": "即散无量诸妙宝花，于虚空中变成宝盖，覆诸大众靡不周遍。",
   "pinyin": "jí sàn wú liàng zhū miào bǎo huā yú xū kōng zhōng biàn chéng bǎo gài fù zhū dà zhòng mǐ bù zhōu biàn",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 61,
   "text": "时波斯匿王即从座起，顶礼佛足，合掌长跪而白佛言：",
   "pinyin": "shí bō sī nì wáng jí cóng zuò qǐ dǐng lǐ fó zú hé zhǎng cháng guì ér bái fó yán",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 62,
   "text": "世尊！",
   "pinyin": "shì zūn",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 63,
   "text": "菩萨摩诃萨，云何护佛果？",
   "pinyin": "pú sà mó hē sà yún hé hù fó guǒ",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 64,
   "text": "云何护十地行？",
   "pinyin": "yún hé hù shí dì xíng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 65,
   "text": "佛告波斯匿王言：",
   "pinyin": "fó gào bō sī nì wáng yán",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 66,
   "text": "护佛果者，诸菩萨摩诃萨应如是住，",
   "pinyin": "hù fó guǒ zhě zhū pú sà mó hē sà yīng rú shì zhù",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 67,
   "text": "教化一切卵生、胎生、湿生、化生，不观色相，不观色如，受、想、行、识，",
   "pinyin": "jiào huà yí qiè luǎn shēng tāi shēng shī shēng huà shēng bù guān sè xiàng bù guān sè rú shòu xiǎng xíng shí",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 68,
   "text": "我人知见、常乐净倒、四摄、六度、二谛四谛、力无畏等一切诸行，",
   "pinyin": "wǒ rén zhī jiàn cháng lè jìng dǎo sì shè liù dù èr dì sì dì lì wú wèi děng yí qiè zhū xíng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 69,
   "text": "乃至菩萨、如来亦复如是，不观相、不观如。",
   "pinyin": "nǎi zhì pú sà rú lái yì fù rú shì bù guān xiàng bù guān rú",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 70,
   "text": "所以者何？",
   "pinyin": "suǒ yǐ zhě hé",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 71,
   "text": "以诸法性即真实故，无来无去、无生无灭，同真际、等法性，",
   "pinyin": "yǐ zhū fǎ xìng jí zhēn shí gù wú lái wú qù wú shēng wú miè tóng zhēn jì děng fǎ xìng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 72,
   "text": "无二无别犹如虚空，蕴、处、界相无我我所。",
   "pinyin": "wú èr wú bié yóu rú xū kōng yùn chù jiè xiàng wú wǒ wǒ suǒ",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 73,
   "text": "是为菩萨摩诃萨修行般若波罗蜜多。",
   "pinyin": "shì wéi pú sà mó hē sà xiū xíng bō rě bō luó mì duō",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 74,
   "text": "波斯匿王白佛言：",
   "pinyin": "bō sī nì wáng bái fó yán",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 75,
   "text": "世尊！",
   "pinyin": "shì zūn",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 76,
   "text": "若菩萨、众生性无二者，菩萨以何相而化众生耶？",
   "pinyin": "ruò pú sà zhòng shēng xìng wú èr zhě pú sà yǐ hé xiàng ér huà zhòng shēng yé",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 77,
   "text": "佛言：",
   "pinyin": "fó yán",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 78,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 79,
   "text": "色、受、想、行、识常乐我净，法性不住色、不住非色。",
   "pinyin": "sè shòu xiǎng xíng shí cháng lè wǒ jìng fǎ xìng bù zhù sè bù zhù fēi sè",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 80,
   "text": "受、想、行、识常乐我净，亦不住净，不住非净。",
   "pinyin": "shòu xiǎng xíng shí cháng lè wǒ jìng yì bù zhù jìng bù zhù fēi jìng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 81,
   "text": "何以故？",
   "pinyin": "hé yǐ gù",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 82,
   "text": "以诸法性悉皆空故，由世谛故，由三假故。",
   "pinyin": "yǐ zhū fǎ xìng xī jiē kōng gù yóu shì dì gù yóu sān jiǎ gù",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 83,
   "text": "一切有情蕴、处、界法，造福、非福、不动行等，因果皆有；",
   "pinyin": "yí qiè yǒu qíng yùn chù jiè fǎ zào fú fēi fú bù dòng xíng děng yīn guǒ jiē yǒu",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 84,
   "text": "三乘贤圣所修诸行，乃至佛果，皆名为有；",
   "pinyin": "sān shèng xián shèng suǒ xiū zhū xíng nǎi zhì fó guǒ jiē míng wéi yǒu",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 85,
   "text": "六十二见亦名为有。",
   "pinyin": "liù shí èr jiàn yì míng wéi yǒu",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 86,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 87,
   "text": "若著名相分别诸法，六趣、四生、三乘行果，即是不见诸法实性。",
   "pinyin": "ruò zhuó míng xiàng fēn bié zhū fǎ liù qù sì shēng sān shèng xíng guǒ jí shì bù jiàn zhū fǎ shí xìng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 88,
   "text": "波斯匿王白佛言：",
   "pinyin": "bō sī nì wáng bái fó yán",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 89,
   "text": "诸法实性，清净平等，非有非无，智云何照？",
   "pinyin": "zhū fǎ shí xìng qīng jìng píng děng fēi yǒu fēi wú zhì yún hé zhào",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 90,
   "text": "佛言：",
   "pinyin": "fó yán",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 91,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 92,
   "text": "智照实性，非有非无。",
   "pinyin": "zhì zhào shí xìng fēi yǒu fēi wú",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 93,
   "text": "所以者何？",
   "pinyin": "suǒ yǐ zhě hé",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 94,
   "text": "法性空故。",
   "pinyin": "fǎ xìng kōng gù",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 95,
   "text": "是即色、受、想、行、识，十二处，十八界；",
   "pinyin": "shì jí sè shòu xiǎng xíng shí shí èr chù shí bā jiè",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 96,
   "text": "士夫六界，十二因缘；",
   "pinyin": "shì fū liù jiè shí èr yīn yuán",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 97,
   "text": "二谛，四谛，一切皆空。",
   "pinyin": "èr dì sì dì yí qiè jiē kōng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 98,
   "text": "是诸法等，即生即灭，即有即空，刹那刹那亦复如是。",
   "pinyin": "shì zhū fǎ děng jí shēng jí miè jí yǒu jí kōng chà nà chà nà yì fù rú shì",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 99,
   "text": "何以故？",
   "pinyin": "hé yǐ gù",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 100,
   "text": "一念中有九十刹那，一刹那经九百生灭，诸有为法悉皆空故。",
   "pinyin": "yī niàn zhōng yǒu jiǔ shí chà nà yī chà nà jīng jiǔ bǎi shēng miè zhū yǒu wéi fǎ xī jiē kōng gù",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 101,
   "text": "以甚深般若波罗蜜多，照见诸法，一切皆空：",
   "pinyin": "yǐ shèn shēn bō rě bō luó mì duō zhào jiàn zhū fǎ yí qiè jiē kōng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 102,
   "text": "内空、外空、内外空、空空、大空、胜义空、有为空、无为空、无始空、毕竟空、",
   "pinyin": "nèi kōng wài kōng nèi wài kōng kōng kōng dà kōng shèng yì kōng yǒu wéi kōng wú wéi kōng wú shǐ kōng bì jìng kōng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 103,
   "text": "散空、本性空、自相空、一切法空、般若波罗蜜多空、因空、佛果空。",
   "pinyin": "sàn kōng běn xìng kōng zì xiàng kōng yí qiè fǎ kōng bō rě bō luó mì duō kōng yīn kōng fó guǒ kōng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 104,
   "text": "空空故空。",
   "pinyin": "kōng kōng gù kōng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 105,
   "text": "诸有为法，",
   "pinyin": "zhū yǒu wéi fǎ",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 106,
   "text": "法集故有、受集故有、名集故有、因集故有、",
   "pinyin": "fǎ jí gù yǒu shòu jí gù yǒu míng jí gù yǒu yīn jí gù yǒu",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 107,
   "text": "果集故有、六趣故有、十地故有、佛果故有，",
   "pinyin": "guǒ jí gù yǒu liù qù gù yǒu shí dì gù yǒu fó guǒ gù yǒu",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 108,
   "text": "一切皆有。",
   "pinyin": "yí qiè jiē yǒu",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 109,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 110,
   "text": "若菩萨住于法相，有我相、人相，有情知见，为住世间即非菩萨。",
   "pinyin": "ruò pú sà zhù yú fǎ xiàng yǒu wǒ xiàng rén xiàng yǒu qíng zhī jiàn wéi zhù shì jiān jí fēi pú sà",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 111,
   "text": "所以者何？",
   "pinyin": "suǒ yǐ zhě hé",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 112,
   "text": "一切诸法悉皆空故。",
   "pinyin": "yí qiè zhū fǎ xī jiē kōng gù",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 113,
   "text": "若于诸法而得不动，不生不灭，无相无无相，不应起见。",
   "pinyin": "ruò yú zhū fǎ ér dé bù dòng bù shēng bù miè wú xiàng wú wú xiàng bù yīng qǐ jiàn",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 114,
   "text": "何以故？",
   "pinyin": "hé yǐ gù",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 115,
   "text": "一切法皆如也。",
   "pinyin": "yí qiè fǎ jiē rú yě",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 116,
   "text": "诸佛、法、僧亦如也。",
   "pinyin": "zhū fó fǎ sēng yì rú yě",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 117,
   "text": "圣智现前最初一念，具足八万四千波罗蜜多，名欢喜地；",
   "pinyin": "shèng zhì xiàn qián zuì chū yī niàn jù zú bā wàn sì qiān bō luó mì duō míng huān xǐ dì",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 118,
   "text": "障尽解脱，运载名乘；",
   "pinyin": "zhàng jìn jiě tuō yùn zài míng shèng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 119,
   "text": "动相灭时，名金刚定；",
   "pinyin": "dòng xiàng miè shí míng jīn gāng dìng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 120,
   "text": "体相平等，名一切智智。",
   "pinyin": "tǐ xiàng píng děng míng yí qiè zhì zhì",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 121,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 122,
   "text": "此般若波罗蜜多文字章句，百佛、千佛、百千万亿一切诸佛而共同说。",
   "pinyin": "cǐ bō rě bō luó mì duō wén zì zhāng jù bǎi fó qiān fó bǎi qiān wàn yì yí qiè zhū fó ér gòng tóng shuō",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 123,
   "text": "若有人于恒河沙三千大千世界，满中七宝以用布施，",
   "pinyin": "ruò yǒu rén yú héng hé shā sān qiān dà qiān shì jiè mǎn zhōng qī bǎo yǐ yòng bù shī",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 124,
   "text": "大千世界一切有情皆得阿罗汉果；",
   "pinyin": "dà qiān shì jiè yí qiè yǒu qíng jiē dé ā luó hàn guǒ",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 125,
   "text": "不如有人于此经中乃至起于一念净信，何况有能受持、读诵、解一句者。",
   "pinyin": "bù rú yǒu rén yú cǐ jīng zhōng nǎi zhì qǐ yú yī niàn jìng xìn hé kuàng yǒu néng shòu chí dú sòng jiě yī jù zhě",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 126,
   "text": "所以者何？",
   "pinyin": "suǒ yǐ zhě hé",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 127,
   "text": "文字性离，无文字相，非法非非法。",
   "pinyin": "wén zì xìng lí wú wén zì xiàng fēi fǎ fēi fēi fǎ",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 128,
   "text": "般若空故，菩萨亦空。",
   "pinyin": "bō rě kōng gù pú sà yì kōng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 129,
   "text": "何以故？",
   "pinyin": "hé yǐ gù",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 130,
   "text": "于十地中，地地皆有始生、住生及以终生，此三十生悉皆是空；",
   "pinyin": "yú shí dì zhōng dì dì jiē yǒu shǐ shēng zhù shēng jí yǐ zhōng shēng cǐ sān shí shēng xī jiē shì kōng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 131,
   "text": "一切智智亦复皆空。",
   "pinyin": "yí qiè zhì zhì yì fù jiē kōng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 132,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 133,
   "text": "若菩萨见境、见智、见说、见受，即非圣见，是愚夫见。",
   "pinyin": "ruò pú sà jiàn jìng jiàn zhì jiàn shuō jiàn shòu jí fēi shèng jiàn shì yú fū jiàn",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 134,
   "text": "有情果报三界虚妄——欲界分别所造诸业，色四静虑定所作业，",
   "pinyin": "yǒu qíng guǒ bào sān jiè xū wàng yù jiè fēn bié suǒ zào zhū yè sè sì jìng lǜ dìng suǒ zuò yè",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 135,
   "text": "无色四空定所起业——三有业果一切皆空，三界根本无明亦空。",
   "pinyin": "wú sè sì kōng dìng suǒ qǐ yè sān yǒu yè guǒ yí qiè jiē kōng sān jiè gēn běn wú míng yì kōng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 136,
   "text": "圣位诸地无漏生灭，于三界中余无明习，变易果报亦复皆空。",
   "pinyin": "shèng wèi zhū dì wú lòu shēng miè yú sān jiè zhōng yú wú míng xí biàn yì guǒ bào yì fù jiē kōng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 137,
   "text": "等觉菩萨得金刚定，二死因果空，一切智亦空。",
   "pinyin": "děng jué pú sà dé jīn gāng dìng èr sǐ yīn guǒ kōng yí qiè zhì yì kōng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 138,
   "text": "佛无上觉种智圆满，择非择灭真净法界，性相平等应用亦空。",
   "pinyin": "fó wú shàng jué zhǒng zhì yuán mǎn zé fēi zé miè zhēn jìng fǎ jiè xìng xiàng píng děng yìng yòng yì kōng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 139,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 140,
   "text": "若有修习般若波罗蜜多，说者、听者，譬如幻士，无说、无听。",
   "pinyin": "ruò yǒu xiū xí bō rě bō luó mì duō shuō zhě tīng zhě pì rú huàn shì wú shuō wú tīng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 141,
   "text": "法同法性，犹如虚空，一切法皆如也。",
   "pinyin": "fǎ tóng fǎ xìng yóu rú xū kōng yí qiè fǎ jiē rú yě",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 142,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 143,
   "text": "菩萨摩诃萨护佛果为若此。",
   "pinyin": "pú sà mó hē sà hù fó guǒ wéi ruò cǐ",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 144,
   "text": "尔时世尊告波斯匿王言：",
   "pinyin": "ěr shí shì zūn gào bō sī nì wáng yán",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 145,
   "text": "汝以何相而观如来？",
   "pinyin": "rǔ yǐ hé xiàng ér guān rú lái",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 146,
   "text": "波斯匿王言：",
   "pinyin": "bō sī nì wáng yán",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 147,
   "text": "观身实相，观佛亦然——无前际、无后际、无中际，不住三际不离三际；",
   "pinyin": "guān shēn shí xiàng guān fó yì rán wú qián jì wú hòu jì wú zhōng jì bù zhù sān jì bù lí sān jì",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 148,
   "text": "不住五蕴不离五蕴；",
   "pinyin": "bù zhù wǔ yùn bù lí wǔ yùn",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 149,
   "text": "不住四大不离四大；",
   "pinyin": "bù zhù sì dà bù lí sì dà",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 150,
   "text": "不住六处不离六处；",
   "pinyin": "bù zhù liù chù bù lí liù chù",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 151,
   "text": "不住三界不离三界；",
   "pinyin": "bù zhù sān jiè bù lí sān jiè",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 152,
   "text": "不住方不离方；",
   "pinyin": "bù zhù fāng bù lí fāng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 153,
   "text": "明无明等非一非异；",
   "pinyin": "míng wú míng děng fēi yī fēi yì",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 154,
   "text": "非此非彼；",
   "pinyin": "fēi cǐ fēi bǐ",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 155,
   "text": "非净非秽；",
   "pinyin": "fēi jìng fēi huì",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 156,
   "text": "非有为非无为；",
   "pinyin": "fēi yǒu wéi fēi wú wéi",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 157,
   "text": "无自相无他相；",
   "pinyin": "wú zì xiàng wú tā xiàng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 158,
   "text": "无名无相；",
   "pinyin": "wú míng wú xiàng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 159,
   "text": "无强无弱；",
   "pinyin": "wú qiáng wú ruò",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 160,
   "text": "无示无说；",
   "pinyin": "wú shì wú shuō",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 161,
   "text": "非施非悭；",
   "pinyin": "fēi shī fēi qiān",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 162,
   "text": "非戒非犯；",
   "pinyin": "fēi jiè fēi fàn",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 163,
   "text": "非忍非恚；",
   "pinyin": "fēi rěn fēi huì",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 164,
   "text": "非进非怠；",
   "pinyin": "fēi jìn fēi dài",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 165,
   "text": "非定非乱；",
   "pinyin": "fēi dìng fēi luàn",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 166,
   "text": "非智非愚；",
   "pinyin": "fēi zhì fēi yú",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 167,
   "text": "非来非去；",
   "pinyin": "fēi lái fēi qù",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 168,
   "text": "非入非出；",
   "pinyin": "fēi rù fēi chū",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 169,
   "text": "非福田非不福田；",
   "pinyin": "fēi fú tián fēi bù fú tián",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 170,
   "text": "非相非无相；",
   "pinyin": "fēi xiàng fēi wú xiàng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 171,
   "text": "非取非舍；",
   "pinyin": "fēi qǔ fēi shě",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 172,
   "text": "非大非小；",
   "pinyin": "fēi dà fēi xiǎo",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 173,
   "text": "非见非闻非觉非知；",
   "pinyin": "fēi jiàn fēi wén fēi jué fēi zhī",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 174,
   "text": "心行处灭，言语道断；",
   "pinyin": "xīn xíng chù miè yán yǔ dào duàn",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 175,
   "text": "同真际、等法性——我以此相而观如来。",
   "pinyin": "tóng zhēn jì děng fǎ xìng wǒ yǐ cǐ xiàng ér guān rú lái",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 176,
   "text": "佛言：",
   "pinyin": "fó yán",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 177,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 178,
   "text": "如汝所说。",
   "pinyin": "rú rǔ suǒ shuō",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 179,
   "text": "诸佛如来力、无畏等恒沙功德，诸不共法悉皆如是。",
   "pinyin": "zhū fó rú lái lì wú wèi děng héng shā gōng dé zhū bù gòng fǎ xī jiē rú shì",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 180,
   "text": "修般若波罗蜜多者应如是观，若他观者名为邪观。",
   "pinyin": "xiū bō rě bō luó mì duō zhě yīng rú shì guān ruò tā guān zhě míng wéi xié guān",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 181,
   "text": "说是法时，无量大众得法眼净。",
   "pinyin": "shuō shì fǎ shí wú liàng dà zhòng dé fǎ yǎn jìng",
   "part": "长行",
   "heading": "观如来品第二"
  },
  {
   "n": 182,
   "text": "尔时，波斯匿王白佛言：",
   "pinyin": "ěr shí bō sī nì wáng bái fó yán",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 183,
   "text": "世尊！",
   "pinyin": "shì zūn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 184,
   "text": "护十地行菩萨摩诃萨，应云何修行？",
   "pinyin": "hù shí dì xíng pú sà mó hē sà yīng yún hé xiū xíng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 185,
   "text": "云何化众生？",
   "pinyin": "yún hé huà zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 186,
   "text": "复以何相而住观察？",
   "pinyin": "fù yǐ hé xiàng ér zhù guān chá",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 187,
   "text": "佛告大王：",
   "pinyin": "fó gào dà wáng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 188,
   "text": "诸菩萨摩诃萨依五忍法以为修行，所谓：",
   "pinyin": "zhū pú sà mó hē sà yī wǔ rěn fǎ yǐ wéi xiū xíng suǒ wèi",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 189,
   "text": "伏忍、信忍、顺忍、无生忍——皆上中下，",
   "pinyin": "fú rěn xìn rěn shùn rěn wú shēng rěn jiē shàng zhōng xià",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 190,
   "text": "于寂灭忍而有上下，名为菩萨修行般若波罗蜜多。",
   "pinyin": "yú jì miè rěn ér yǒu shàng xià míng wéi pú sà xiū xíng bō rě bō luó mì duō",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 191,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 192,
   "text": "初伏忍位，起习种性，修十住行。",
   "pinyin": "chū fú rěn wèi qǐ xí zhǒng xìng xiū shí zhù xíng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 193,
   "text": "初发心相，有恒河沙众生，见佛法僧，发于十信，所谓：",
   "pinyin": "chū fā xīn xiàng yǒu héng hé shā zhòng shēng jiàn fó fǎ sēng fā yú shí xìn suǒ wèi",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 194,
   "text": "信心、念心、精进心、慧心、定心、不退心、戒心、愿心、护法心、回向心。",
   "pinyin": "xìn xīn niàn xīn jīng jìn xīn huì xīn dìng xīn bù tuì xīn jiè xīn yuàn xīn hù fǎ xīn huí xiàng xīn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 195,
   "text": "具此十心而能少分化诸众生，超过二乘一切善地，",
   "pinyin": "jù cǐ shí xīn ér néng shǎo fēn huà zhū zhòng shēng chāo guò èr shèng yí qiè shàn dì",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 196,
   "text": "是为菩萨初长养心，为圣胎故。",
   "pinyin": "shì wéi pú sà chū zhǎng yǎng xīn wéi shèng tāi gù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 197,
   "text": "复次，性种性菩萨修行十种波罗蜜多，起十对治，所谓：",
   "pinyin": "fù cì xìng zhǒng xìng pú sà xiū xíng shí zhǒng bō luó mì duō qǐ shí duì zhì suǒ wèi",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 198,
   "text": "观察身、受、心、法，不净、诸苦、无常、无我；",
   "pinyin": "guān chá shēn shòu xīn fǎ bù jìng zhū kǔ wú cháng wú wǒ",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 199,
   "text": "治贪、瞋、痴三不善根，起施、慈、慧三种善根；",
   "pinyin": "zhì tān chēn chī sān bù shàn gēn qǐ shī cí huì sān zhǒng shàn gēn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 200,
   "text": "观察三世过去因忍、现在因果忍、未来果忍。",
   "pinyin": "guān chá sān shì guò qù yīn rěn xiàn zài yīn guǒ rěn wèi lái guǒ rěn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 201,
   "text": "此位菩萨广利众生，超过我见、人见、众生等想，外道倒想所不能坏。",
   "pinyin": "cǐ wèi pú sà guǎng lì zhòng shēng chāo guò wǒ jiàn rén jiàn zhòng shēng děng xiǎng wài dào dǎo xiǎng suǒ bù néng huài",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 202,
   "text": "复次，道种性菩萨修十回向，起十忍心，谓观五蕴——色、受、想、行、识，",
   "pinyin": "fù cì dào zhǒng xìng pú sà xiū shí huí xiàng qǐ shí rěn xīn wèi guān wǔ yùn sè shòu xiǎng xíng shí",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 203,
   "text": "得戒忍、定忍、慧忍、解脱忍、解脱知见忍；",
   "pinyin": "dé jiè rěn dìng rěn huì rěn jiě tuō rěn jiě tuō zhī jiàn rěn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 204,
   "text": "观三界因果，得空忍、无想忍、无愿忍；",
   "pinyin": "guān sān jiè yīn guǒ dé kōng rěn wú xiǎng rěn wú yuàn rěn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 205,
   "text": "观二谛假实诸法无常得无常忍，一切法空得无生忍。",
   "pinyin": "guān èr dì jiǎ shí zhū fǎ wú cháng dé wú cháng rěn yí qiè fǎ kōng dé wú shēng rěn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 206,
   "text": "此位菩萨作转轮王，能广化利一切众生。",
   "pinyin": "cǐ wèi pú sà zuò zhuàn lún wáng néng guǎng huà lì yí qiè zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 207,
   "text": "复次，信忍菩萨，谓：",
   "pinyin": "fù cì xìn rěn pú sà wèi",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 208,
   "text": "欢喜地、离垢地、发光地，能断三障色烦恼缚；",
   "pinyin": "huān xǐ dì lí gòu dì fā guāng dì néng duàn sān zhàng sè fán nǎo fù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 209,
   "text": "行四摄法——布施、爱语、利行、同事；",
   "pinyin": "xíng sì shè fǎ bù shī ài yǔ lì xíng tóng shì",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 210,
   "text": "修四无量——慈无量心、悲无量心、喜无量心、舍无量心；",
   "pinyin": "xiū sì wú liàng cí wú liàng xīn bēi wú liàng xīn xǐ wú liàng xīn shě wú liàng xīn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 211,
   "text": "具四弘愿——断诸缠盖，常化众生，修佛知见，成无上觉；",
   "pinyin": "jù sì hóng yuàn duàn zhū chán gài cháng huà zhòng shēng xiū fó zhī jiàn chéng wú shàng jué",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 212,
   "text": "住三脱门——空解脱门、无相解脱门、无愿解脱门。",
   "pinyin": "zhù sān tuō mén kōng jiě tuō mén wú xiàng jiě tuō mén wú yuàn jiě tuō mén",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 213,
   "text": "此是菩萨摩诃萨从初发心至一切智诸行根本，利益安乐一切众生。",
   "pinyin": "cǐ shì pú sà mó hē sà cóng chū fā xīn zhì yí qiè zhì zhū xíng gēn běn lì yì ān lè yí qiè zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 214,
   "text": "复次，顺忍菩萨，谓：",
   "pinyin": "fù cì shùn rěn pú sà wèi",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 215,
   "text": "焰慧地、难胜地、现前地，能断三障，心烦恼缚，",
   "pinyin": "yàn huì dì nán shèng dì xiàn qián dì néng duàn sān zhàng xīn fán nǎo fù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 216,
   "text": "能于一身遍往十方亿佛刹土，现不可说神通变化，利乐众生。",
   "pinyin": "néng yú yī shēn biàn wǎng shí fāng yì fó chà tǔ xiàn bù kě shuō shén tōng biàn huà lì lè zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 217,
   "text": "复次，无生忍菩萨，谓：",
   "pinyin": "fù cì wú shēng rěn pú sà wèi",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 218,
   "text": "远行地、不动地、善慧地，能断三障色心习气，",
   "pinyin": "yuǎn xíng dì bù dòng dì shàn huì dì néng duàn sān zhàng sè xīn xí qì",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 219,
   "text": "而能示现不可说身，随类饶益一切众生。",
   "pinyin": "ér néng shì xiàn bù kě shuō shēn suí lèi ráo yì yí qiè zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 220,
   "text": "复次，寂灭忍者，佛与菩萨同依此忍，",
   "pinyin": "fù cì jì miè rěn zhě fó yǔ pú sà tóng yī cǐ rěn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 221,
   "text": "金刚喻定住下忍位名为菩萨，至于上忍名一切智。",
   "pinyin": "jīn gāng yù dìng zhù xià rěn wèi míng wéi pú sà zhì yú shàng rěn míng yí qiè zhì",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 222,
   "text": "观胜义谛，断无明相，是为等觉；",
   "pinyin": "guān shèng yì dì duàn wú míng xiàng shì wéi děng jué",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 223,
   "text": "一相无相，平等无二，为第十一一切智地。",
   "pinyin": "yī xiàng wú xiàng píng děng wú èr wéi dì shí yī yí qiè zhì dì",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 224,
   "text": "非有非无，湛然清净，无来无去，常住不变，同真际、等法性，",
   "pinyin": "fēi yǒu fēi wú zhàn rán qīng jìng wú lái wú qù cháng zhù bù biàn tóng zhēn jì děng fǎ xìng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 225,
   "text": "无缘大悲常化众生，乘一切智乘来化三界。",
   "pinyin": "wú yuán dà bēi cháng huà zhòng shēng chéng yí qiè zhì shèng lái huà sān jiè",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 226,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 227,
   "text": "诸众生类一切烦恼——业异熟果二十二根——不出三界，诸佛示导；",
   "pinyin": "zhū zhòng shēng lèi yí qiè fán nǎo yè yì shú guǒ èr shí èr gēn bù chū sān jiè zhū fó shì dǎo",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 228,
   "text": "应、化、法身亦不离此。",
   "pinyin": "yìng huà fǎ shēn yì bù lí cǐ",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 229,
   "text": "若有说言：",
   "pinyin": "ruò yǒu shuō yán",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 230,
   "text": "于三界外，别更有一众生界。",
   "pinyin": "yú sān jiè wài bié gèng yǒu yī zhòng shēng jiè",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 231,
   "text": "者，即是外道大有经说。",
   "pinyin": "zhě jí shì wài dào dà yǒu jīng shuō",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 232,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 233,
   "text": "我常语诸众生：",
   "pinyin": "wǒ cháng yǔ zhū zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 234,
   "text": "但断三界无明尽者，即名为佛。",
   "pinyin": "dàn duàn sān jiè wú míng jìn zhě jí míng wéi fó",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 235,
   "text": "自性清净，名本觉性，即是诸佛一切智智；",
   "pinyin": "zì xìng qīng jìng míng běn jué xìng jí shì zhū fó yí qiè zhì zhì",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 236,
   "text": "由此得为众生之本，亦是诸佛菩萨行本，",
   "pinyin": "yóu cǐ dé wéi zhòng shēng zhī běn yì shì zhū fó pú sà xíng běn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 237,
   "text": "是为菩萨本所修行五忍法中十四忍也。",
   "pinyin": "shì wéi pú sà běn suǒ xiū xíng wǔ rěn fǎ zhōng shí sì rěn yě",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 238,
   "text": "佛言：",
   "pinyin": "fó yán",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 239,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 240,
   "text": "汝先问言：",
   "pinyin": "rǔ xiān wèn yán",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 241,
   "text": "菩萨云何化众生？",
   "pinyin": "pú sà yún hé huà zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 242,
   "text": "者，菩萨摩诃萨应如是化——从初一地至后一地，自所行处及佛行处，",
   "pinyin": "zhě pú sà mó hē sà yīng rú shì huà cóng chū yī dì zhì hòu yī dì zì suǒ xíng chù jí fó xíng chù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 243,
   "text": "一切知见故——若菩萨摩诃萨住百佛刹，作赡部洲转轮圣王，",
   "pinyin": "yí qiè zhī jiàn gù ruò pú sà mó hē sà zhù bǎi fó chà zuò shàn bù zhōu zhuàn lún shèng wáng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 244,
   "text": "修百法明门，以檀波罗蜜多住平等心，化四天下一切众生；",
   "pinyin": "xiū bǎi fǎ míng mén yǐ tán bō luó mì duō zhù píng děng xīn huà sì tiān xià yí qiè zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 245,
   "text": "若菩萨摩诃萨住千佛刹，作忉利天王，修千法明门，说十善道化一切众生；",
   "pinyin": "ruò pú sà mó hē sà zhù qiān fó chà zuò dāo lì tiān wáng xiū qiān fǎ míng mén shuō shí shàn dào huà yí qiè zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 246,
   "text": "若菩萨摩诃萨住万佛刹，作夜摩天王，修万法明门，依四禅定化一切众生；",
   "pinyin": "ruò pú sà mó hē sà zhù wàn fó chà zuò yè mó tiān wáng xiū wàn fǎ míng mén yī sì chán dìng huà yí qiè zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 247,
   "text": "若菩萨摩诃萨住亿佛刹，作睹史多天王，",
   "pinyin": "ruò pú sà mó hē sà zhù yì fó chà zuò dǔ shǐ duō tiān wáng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 248,
   "text": "修亿法明门，行菩提分法化一切众生；",
   "pinyin": "xiū yì fǎ míng mén xíng pú tí fēn fǎ huà yí qiè zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 249,
   "text": "若菩萨摩诃萨住百亿佛刹，作化乐天王，",
   "pinyin": "ruò pú sà mó hē sà zhù bǎi yì fó chà zuò huà lè tiān wáng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 250,
   "text": "修百亿法明门，二谛四谛化一切众生；",
   "pinyin": "xiū bǎi yì fǎ míng mén èr dì sì dì huà yí qiè zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 251,
   "text": "若菩萨摩诃萨住千亿佛刹，作他化自在天王，",
   "pinyin": "ruò pú sà mó hē sà zhù qiān yì fó chà zuò tā huà zì zài tiān wáng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 252,
   "text": "修千亿法明门，十二因缘智化一切众生；",
   "pinyin": "xiū qiān yì fǎ míng mén shí èr yīn yuán zhì huà yí qiè zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 253,
   "text": "若菩萨摩诃萨住万亿佛刹，作初禅梵王，",
   "pinyin": "ruò pú sà mó hē sà zhù wàn yì fó chà zuò chū chán fàn wáng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 254,
   "text": "修万亿法明门，方便善巧智化一切众生；",
   "pinyin": "xiū wàn yì fǎ míng mén fāng biàn shàn qiǎo zhì huà yí qiè zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 255,
   "text": "若菩萨摩诃萨住百万微尘数佛刹，作二禅梵王，",
   "pinyin": "ruò pú sà mó hē sà zhù bǎi wàn wēi chén shù fó chà zuò èr chán fàn wáng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 256,
   "text": "修百万微尘数法明门，双照平等神通愿智化一切众生；",
   "pinyin": "xiū bǎi wàn wēi chén shù fǎ míng mén shuāng zhào píng děng shén tōng yuàn zhì huà yí qiè zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 257,
   "text": "若菩萨摩诃萨住百万亿阿僧祇微尘数佛刹，作三禅梵王，",
   "pinyin": "ruò pú sà mó hē sà zhù bǎi wàn yì ā sēng qí wēi chén shù fó chà zuò sān chán fàn wáng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 258,
   "text": "修百万亿阿僧祇微尘数法明门，以四无碍智化一切众生；",
   "pinyin": "xiū bǎi wàn yì ā sēng qí wēi chén shù fǎ míng mén yǐ sì wú ài zhì huà yí qiè zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 259,
   "text": "若菩萨摩诃萨住不可说不可说佛刹，作第四禅大梵天王，为三界王，",
   "pinyin": "ruò pú sà mó hē sà zhù bù kě shuō bù kě shuō fó chà zuò dì sì chán dà fàn tiān wáng wéi sān jiè wáng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 260,
   "text": "修不可说不可说法明门，得理尽三昧，同佛行处，尽三界原，",
   "pinyin": "xiū bù kě shuō bù kě shuō fǎ míng mén dé lǐ jìn sān mèi tóng fó xíng chù jìn sān jiè yuán",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 261,
   "text": "普利众生，如佛境界，是为菩萨摩诃萨现诸王身化导之事。",
   "pinyin": "pǔ lì zhòng shēng rú fó jìng jiè shì wéi pú sà mó hē sà xiàn zhū wáng shēn huà dǎo zhī shì",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 262,
   "text": "十方如来亦复如是，证无上觉，常遍法界，利乐众生。",
   "pinyin": "shí fāng rú lái yì fù rú shì zhèng wú shàng jué cháng biàn fǎ jiè lì lè zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 263,
   "text": "尔时，一切大众即从座起，散不可说花，焚不可说香，供养、恭敬、称赞如来。",
   "pinyin": "ěr shí yí qiè dà zhòng jí cóng zuò qǐ sàn bù kě shuō huā fén bù kě shuō xiāng gòng yǎng gōng jìng chēng zàn rú lái",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 264,
   "text": "时波斯匿王即于佛前以偈赞曰：",
   "pinyin": "shí bō sī nì wáng jí yú fó qián yǐ jì zàn yuē",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 265,
   "text": "世尊导师金刚体，",
   "pinyin": "shì zūn dǎo shī jīn gāng tǐ",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 266,
   "text": "心行寂灭转法轮，",
   "pinyin": "xīn xíng jì miè zhuǎn fǎ lún",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 267,
   "text": "八辩圆音为开演，",
   "pinyin": "bā biàn yuán yīn wèi kāi yǎn",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 268,
   "text": "时众得道百万亿。",
   "pinyin": "shí zhòng dé dào bǎi wàn yì",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 269,
   "text": "天人俱修出离行，",
   "pinyin": "tiān rén jù xiū chū lí xíng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 270,
   "text": "能习一切菩萨道，",
   "pinyin": "néng xí yí qiè pú sà dào",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 271,
   "text": "五忍功德妙法门，",
   "pinyin": "wǔ rěn gōng dé miào fǎ mén",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 272,
   "text": "十四菩萨能谛了。",
   "pinyin": "shí sì pú sà néng dì liǎo",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 273,
   "text": "三贤十圣忍中行，",
   "pinyin": "sān xián shí shèng rěn zhōng xíng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 274,
   "text": "唯佛一人能尽原，",
   "pinyin": "wéi fó yī rén néng jìn yuán",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 275,
   "text": "佛法众海三宝藏，",
   "pinyin": "fó fǎ zhòng hǎi sān bǎo zàng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 276,
   "text": "无量功德于中摄。",
   "pinyin": "wú liàng gōng dé yú zhōng shè",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 277,
   "text": "十善菩萨发大心，",
   "pinyin": "shí shàn pú sà fā dà xīn",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 278,
   "text": "长别三界苦轮海，",
   "pinyin": "cháng bié sān jiè kǔ lún hǎi",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 279,
   "text": "中下品善粟散王，",
   "pinyin": "zhōng xià pǐn shàn sù sàn wáng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 280,
   "text": "上品十善铁轮王，",
   "pinyin": "shàng pǐn shí shàn tiě lún wáng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 281,
   "text": "习种铜轮二天下，",
   "pinyin": "xí zhǒng tóng lún èr tiān xià",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 282,
   "text": "银轮三天性种性，",
   "pinyin": "yín lún sān tiān xìng zhǒng xìng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 283,
   "text": "道种坚德转轮王，",
   "pinyin": "dào zhǒng jiān dé zhuàn lún wáng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 284,
   "text": "七宝金轮四天下，",
   "pinyin": "qī bǎo jīn lún sì tiān xià",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 285,
   "text": "伏忍圣胎三十人，",
   "pinyin": "fú rěn shèng tāi sān shí rén",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 286,
   "text": "十住十行十回向，",
   "pinyin": "shí zhù shí xíng shí huí xiàng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 287,
   "text": "三世诸佛于中学，",
   "pinyin": "sān shì zhū fó yú zhōng xué",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 288,
   "text": "无不由此伏忍生，",
   "pinyin": "wú bù yóu cǐ fú rěn shēng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 289,
   "text": "一切菩萨行根本，",
   "pinyin": "yí qiè pú sà xíng gēn běn",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 290,
   "text": "是故发心信心难。",
   "pinyin": "shì gù fā xīn xìn xīn nán",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 291,
   "text": "若得信心必不退，",
   "pinyin": "ruò dé xìn xīn bì bù tuì",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 292,
   "text": "进入无生初地道，",
   "pinyin": "jìn rù wú shēng chū dì dào",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 293,
   "text": "化利自他悉平等，",
   "pinyin": "huà lì zì tā xī píng děng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 294,
   "text": "是名菩萨初发心。",
   "pinyin": "shì míng pú sà chū fā xīn",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 295,
   "text": "欢喜菩萨转轮王，",
   "pinyin": "huān xǐ pú sà zhuàn lún wáng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 296,
   "text": "初照二谛平等理，",
   "pinyin": "chū zhào èr dì píng děng lǐ",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 297,
   "text": "权化有情游百国，",
   "pinyin": "quán huà yǒu qíng yóu bǎi guó",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 298,
   "text": "檀施清净利群生。",
   "pinyin": "tán shī qīng jìng lì qún shēng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 299,
   "text": "入理般若名为住，",
   "pinyin": "rù lǐ bō rě míng wéi zhù",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 300,
   "text": "住生德行名为地，",
   "pinyin": "zhù shēng dé xíng míng wéi dì",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 301,
   "text": "初住一心具众德，",
   "pinyin": "chū zhù yī xīn jù zhòng dé",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 302,
   "text": "于胜义中而不动。",
   "pinyin": "yú shèng yì zhōng ér bù dòng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 303,
   "text": "离垢菩萨忉利王，",
   "pinyin": "lí gòu pú sà dāo lì wáng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 304,
   "text": "现形六趣千国土，",
   "pinyin": "xiàn xíng liù qù qiān guó tǔ",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 305,
   "text": "戒足清净悉圆满，",
   "pinyin": "jiè zú qīng jìng xī yuán mǎn",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 306,
   "text": "永离误犯诸过失。",
   "pinyin": "yǒng lí wù fàn zhū guò shī",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 307,
   "text": "无相无缘真实性，",
   "pinyin": "wú xiàng wú yuán zhēn shí xìng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 308,
   "text": "无体无生无二照，",
   "pinyin": "wú tǐ wú shēng wú èr zhào",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 309,
   "text": "发光菩萨夜摩王，",
   "pinyin": "fā guāng pú sà yè mó wáng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 310,
   "text": "应形往万诸佛刹。",
   "pinyin": "yìng xíng wǎng wàn zhū fó chà",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 311,
   "text": "善能通达三摩地，",
   "pinyin": "shàn néng tōng dá sān mó dì",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 312,
   "text": "隐显自在具三明，",
   "pinyin": "yǐn xiǎn zì zài jù sān míng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 313,
   "text": "欢喜离垢与发光，",
   "pinyin": "huān xǐ lí gòu yǔ fā guāng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 314,
   "text": "能灭色缚诸烦恼，",
   "pinyin": "néng miè sè fù zhū fán nǎo",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 315,
   "text": "具观一切身口业，",
   "pinyin": "jù guān yí qiè shēn kǒu yè",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 316,
   "text": "法性清净照皆圆，",
   "pinyin": "fǎ xìng qīng jìng zhào jiē yuán",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 317,
   "text": "焰慧菩萨大精进，",
   "pinyin": "yàn huì pú sà dà jīng jìn",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 318,
   "text": "睹史天王游亿刹，",
   "pinyin": "dǔ shǐ tiān wáng yóu yì chà",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 319,
   "text": "实智寂灭方便智，",
   "pinyin": "shí zhì jì miè fāng biàn zhì",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 320,
   "text": "达无生理照空有，",
   "pinyin": "dá wú shēng lǐ zhào kōng yǒu",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 321,
   "text": "难胜菩萨得平等，",
   "pinyin": "nán shèng pú sà dé píng děng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 322,
   "text": "化乐天王百亿国。",
   "pinyin": "huà lè tiān wáng bǎi yì guó",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 323,
   "text": "空空谛观无二相，",
   "pinyin": "kōng kōng dì guān wú èr xiàng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 324,
   "text": "垂形六趣靡不周，",
   "pinyin": "chuí xíng liù qù mǐ bù zhōu",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 325,
   "text": "现前菩萨自在王，",
   "pinyin": "xiàn qián pú sà zì zài wáng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 326,
   "text": "照见缘生相无二，",
   "pinyin": "zhào jiàn yuán shēng xiàng wú èr",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 327,
   "text": "胜义智光能遍满，",
   "pinyin": "shèng yì zhì guāng néng biàn mǎn",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 328,
   "text": "往千亿土化众生。",
   "pinyin": "wǎng qiān yì tǔ huà zhòng shēng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 329,
   "text": "焰慧难胜现前地，",
   "pinyin": "yàn huì nán shèng xiàn qián dì",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 330,
   "text": "能断三障迷心惑，",
   "pinyin": "néng duàn sān zhàng mí xīn huò",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 331,
   "text": "空慧寂然无缘观，",
   "pinyin": "kōng huì jì rán wú yuán guān",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 332,
   "text": "还照心空无量境。",
   "pinyin": "huán zhào xīn kōng wú liàng jìng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 333,
   "text": "远行菩萨初禅王，",
   "pinyin": "yuǎn xíng pú sà chū chán wáng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 334,
   "text": "住于无相无生忍，",
   "pinyin": "zhù yú wú xiàng wú shēng rěn",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 335,
   "text": "方便善巧悉平等，",
   "pinyin": "fāng biàn shàn qiǎo xī píng děng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 336,
   "text": "常万亿土化群生。",
   "pinyin": "cháng wàn yì tǔ huà qún shēng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 337,
   "text": "进入不动法流地，",
   "pinyin": "jìn rù bù dòng fǎ liú dì",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 338,
   "text": "永无分段超诸有，",
   "pinyin": "yǒng wú fēn duàn chāo zhū yǒu",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 339,
   "text": "常观胜义照无二，",
   "pinyin": "cháng guān shèng yì zhào wú èr",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 340,
   "text": "二十一生空寂行，",
   "pinyin": "èr shí yī shēng kōng jì xíng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 341,
   "text": "顺道法爱无明习，",
   "pinyin": "shùn dào fǎ ài wú míng xí",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 342,
   "text": "远行大士独能断。",
   "pinyin": "yuǎn xíng dà shì dú néng duàn",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 343,
   "text": "不动菩萨二禅王，",
   "pinyin": "bù dòng pú sà èr chán wáng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 344,
   "text": "得变易身常自在，",
   "pinyin": "dé biàn yì shēn cháng zì zài",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 345,
   "text": "能于百万微尘刹，",
   "pinyin": "néng yú bǎi wàn wēi chén chà",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 346,
   "text": "随其形类化众生，",
   "pinyin": "suí qí xíng lèi huà zhòng shēng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 347,
   "text": "悉知三世无量劫，",
   "pinyin": "xī zhī sān shì wú liàng jié",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 348,
   "text": "于第一义而不动。",
   "pinyin": "yú dì yī yì ér bù dòng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 349,
   "text": "善慧菩萨三禅王，",
   "pinyin": "shàn huì pú sà sān chán wáng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 350,
   "text": "能于千恒一时现，",
   "pinyin": "néng yú qiān héng yī shí xiàn",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 351,
   "text": "常在无为空寂行，",
   "pinyin": "cháng zài wú wéi kōng jì xíng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 352,
   "text": "恒沙佛藏一念了。",
   "pinyin": "héng shā fó zàng yī niàn liǎo",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 353,
   "text": "法云菩萨四禅王，",
   "pinyin": "fǎ yún pú sà sì chán wáng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 354,
   "text": "于亿恒土化群生，",
   "pinyin": "yú yì héng tǔ huà qún shēng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 355,
   "text": "始入金刚一切了，",
   "pinyin": "shǐ rù jīn gāng yí qiè liǎo",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 356,
   "text": "二十九生永已度，",
   "pinyin": "èr shí jiǔ shēng yǒng yǐ dù",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 357,
   "text": "寂灭忍中下忍观，",
   "pinyin": "jì miè rěn zhōng xià rěn guān",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 358,
   "text": "一转妙觉无等等。",
   "pinyin": "yī zhuǎn miào jué wú děng děng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 359,
   "text": "不动善慧法云地，",
   "pinyin": "bù dòng shàn huì fǎ yún dì",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 360,
   "text": "除前所有无明习，",
   "pinyin": "chú qián suǒ yǒu wú míng xí",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 361,
   "text": "无明习相识俱转，",
   "pinyin": "wú míng xí xiàng shí jù zhuǎn",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 362,
   "text": "二谛理圆无不尽。",
   "pinyin": "èr dì lǐ yuán wú bù jìn",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 363,
   "text": "正觉无相遍法界，",
   "pinyin": "zhèng jué wú xiàng biàn fǎ jiè",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 364,
   "text": "三十生尽智圆明，",
   "pinyin": "sān shí shēng jìn zhì yuán míng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 365,
   "text": "寂照无为真解脱，",
   "pinyin": "jì zhào wú wéi zhēn jiě tuō",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 366,
   "text": "大悲应现无与等，",
   "pinyin": "dà bēi yìng xiàn wú yǔ děng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 367,
   "text": "湛然不动常安隐，",
   "pinyin": "zhàn rán bù dòng cháng ān yǐn",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 368,
   "text": "光明遍照无所照，",
   "pinyin": "guāng míng biàn zhào wú suǒ zhào",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 369,
   "text": "三贤十圣住果报，",
   "pinyin": "sān xián shí shèng zhù guǒ bào",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 370,
   "text": "唯佛一人居净土。",
   "pinyin": "wéi fó yī rén jū jìng tǔ",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 371,
   "text": "一切有情皆暂住，",
   "pinyin": "yí qiè yǒu qíng jiē zàn zhù",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 372,
   "text": "登金刚原常不动，",
   "pinyin": "dēng jīn gāng yuán cháng bù dòng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 373,
   "text": "如来三业德无量，",
   "pinyin": "rú lái sān yè dé wú liàng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 374,
   "text": "随诸众生等怜愍。",
   "pinyin": "suí zhū zhòng shēng děng lián mǐn",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 375,
   "text": "法王无上人中树，",
   "pinyin": "fǎ wáng wú shàng rén zhōng shù",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 376,
   "text": "普荫大众无量光，",
   "pinyin": "pǔ yìn dà zhòng wú liàng guāng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 377,
   "text": "口常说法非无义，",
   "pinyin": "kǒu cháng shuō fǎ fēi wú yì",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 378,
   "text": "心智寂灭无缘照。",
   "pinyin": "xīn zhì jì miè wú yuán zhào",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 379,
   "text": "人中师子为演说，",
   "pinyin": "rén zhōng shī zǐ wèi yǎn shuō",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 380,
   "text": "甚深句义未曾有，",
   "pinyin": "shèn shēn jù yì wèi céng yǒu",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 381,
   "text": "尘沙刹土悉震动，",
   "pinyin": "chén shā chà tǔ xī zhèn dòng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 382,
   "text": "大众欢喜皆蒙益，",
   "pinyin": "dà zhòng huān xǐ jiē méng yì",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 383,
   "text": "世尊善说十四王，",
   "pinyin": "shì zūn shàn shuō shí sì wáng",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 384,
   "text": "是故我今头面礼。",
   "pinyin": "shì gù wǒ jīn tóu miàn lǐ",
   "part": "偈颂",
   "heading": "菩萨行品第三"
  },
  {
   "n": 385,
   "text": "尔时，百万亿恒河沙大众，闻佛世尊及波斯匿王说十四忍无量功德，",
   "pinyin": "ěr shí bǎi wàn yì héng hé shā dà zhòng wén fó shì zūn jí bō sī nì wáng shuō shí sì rěn wú liàng gōng dé",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 386,
   "text": "获大法利，闻法悟解，得无生忍，入于正位。",
   "pinyin": "huò dà fǎ lì wén fǎ wù jiě dé wú shēng rěn rù yú zhèng wèi",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 387,
   "text": "尔时，世尊告大众言：",
   "pinyin": "ěr shí shì zūn gào dà zhòng yán",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 388,
   "text": "是波斯匿王，已于过去十千劫龙光王佛法中为四地菩萨，我为八地菩萨；",
   "pinyin": "shì bō sī nì wáng yǐ yú guò qù shí qiān jié lóng guāng wáng fó fǎ zhōng wéi sì dì pú sà wǒ wéi bā dì pú sà",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 389,
   "text": "今于我前大师子吼。",
   "pinyin": "jīn yú wǒ qián dà shī zǐ hǒu",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 390,
   "text": "如是，如是！",
   "pinyin": "rú shì rú shì",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 391,
   "text": "如汝所说。",
   "pinyin": "rú rǔ suǒ shuō",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 392,
   "text": "得真实义不可思议，唯佛与佛乃知斯事。",
   "pinyin": "dé zhēn shí yì bù kě sī yì wéi fó yǔ fó nǎi zhī sī shì",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 393,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 394,
   "text": "此十四忍，诸佛法身、诸菩萨行，不可思议，不可称量。",
   "pinyin": "cǐ shí sì rěn zhū fó fǎ shēn zhū pú sà xíng bù kě sī yì bù kě chēng liàng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 395,
   "text": "何以故？",
   "pinyin": "hé yǐ gù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 396,
   "text": "一切诸佛，皆于般若波罗蜜多中生、般若波罗蜜多中化、般若波罗蜜多中灭；",
   "pinyin": "yí qiè zhū fó jiē yú bō rě bō luó mì duō zhōng shēng bō rě bō luó mì duō zhōng huà bō rě bō luó mì duō zhōng miè",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 397,
   "text": "而实诸佛，生无所生、化无所化、灭无所灭。",
   "pinyin": "ér shí zhū fó shēng wú suǒ shēng huà wú suǒ huà miè wú suǒ miè",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 398,
   "text": "第一无二，非相非无相，无自无他，无来无去，如虚空故。",
   "pinyin": "dì yī wú èr fēi xiàng fēi wú xiàng wú zì wú tā wú lái wú qù rú xū kōng gù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 399,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 400,
   "text": "一切众生，性无生灭，由诸法集幻化而有，",
   "pinyin": "yí qiè zhòng shēng xìng wú shēng miè yóu zhū fǎ jí huàn huà ér yǒu",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 401,
   "text": "蕴、处、界相无合无散，法同法性，寂然空故。",
   "pinyin": "yùn chù jiè xiàng wú hé wú sàn fǎ tóng fǎ xìng jì rán kōng gù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 402,
   "text": "一切众生，自性清净，所作诸行无缚无解，非因非果非不因果；",
   "pinyin": "yí qiè zhòng shēng zì xìng qīng jìng suǒ zuò zhū xíng wú fù wú jiě fēi yīn fēi guǒ fēi bù yīn guǒ",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 403,
   "text": "诸苦受行烦恼，所知我相、人相，知见受者，一切空故。",
   "pinyin": "zhū kǔ shòu xíng fán nǎo suǒ zhī wǒ xiàng rén xiàng zhī jiàn shòu zhě yí qiè kōng gù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 404,
   "text": "法境界空，空、无相、无作，不顺颠倒不顺幻化，",
   "pinyin": "fǎ jìng jiè kōng kōng wú xiàng wú zuò bù shùn diān dǎo bù shùn huàn huà",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 405,
   "text": "无六趣相，无四生相，无圣人相，无三宝相，如虚空故。",
   "pinyin": "wú liù qù xiàng wú sì shēng xiàng wú shèng rén xiàng wú sān bǎo xiàng rú xū kōng gù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 406,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 407,
   "text": "甚深般若，无知无见，不行不缘，不舍不受，",
   "pinyin": "shèn shēn bō rě wú zhī wú jiàn bù xíng bù yuán bù shě bù shòu",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 408,
   "text": "正住观察而无照相，行斯道者如虚空故。",
   "pinyin": "zhèng zhù guān chá ér wú zhào xiàng xíng sī dào zhě rú xū kōng gù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 409,
   "text": "法相如是，有所得心、无所得心皆不可得。",
   "pinyin": "fǎ xiàng rú shì yǒu suǒ dé xīn wú suǒ dé xīn jiē bù kě dé",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 410,
   "text": "是以般若，非即五蕴非离五蕴，非即众生非离众生，",
   "pinyin": "shì yǐ bō rě fēi jí wǔ yùn fēi lí wǔ yùn fēi jí zhòng shēng fēi lí zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 411,
   "text": "非即境界非离境界，非即行解非离行解，如是等相不可思量。",
   "pinyin": "fēi jí jìng jiè fēi lí jìng jiè fēi jí xíng jiě fēi lí xíng jiě rú shì děng xiàng bù kě sī liàng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 412,
   "text": "是故一切菩萨摩诃萨所修诸行，未至究竟而于中行，",
   "pinyin": "shì gù yí qiè pú sà mó hē sà suǒ xiū zhū xíng wèi zhì jiū jìng ér yú zhōng xíng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 413,
   "text": "一切诸佛知如幻化，得无住相而于中化，故十四忍不可思量。",
   "pinyin": "yí qiè zhū fó zhī rú huàn huà dé wú zhù xiàng ér yú zhōng huà gù shí sì rěn bù kě sī liàng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 414,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 415,
   "text": "汝今所说此功德藏，有大利益一切众生。",
   "pinyin": "rǔ jīn suǒ shuō cǐ gōng dé zàng yǒu dà lì yì yí qiè zhòng shēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 416,
   "text": "假使无量恒河沙数十地菩萨说是功德，百千亿分如海一滴，",
   "pinyin": "jiǎ shǐ wú liàng héng hé shā shù shí dì pú sà shuō shì gōng dé bǎi qiān yì fēn rú hǎi yī dī",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 417,
   "text": "三世诸佛如实能知，一切贤圣悉皆称赞，是故我今略述所说少分功德。",
   "pinyin": "sān shì zhū fó rú shí néng zhī yí qiè xián shèng xī jiē chēng zàn shì gù wǒ jīn lüè shù suǒ shuō shǎo fēn gōng dé",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 418,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 419,
   "text": "此十四忍，十方世界过去、现在一切菩萨之所修行，",
   "pinyin": "cǐ shí sì rěn shí fāng shì jiè guò qù xiàn zài yí qiè pú sà zhī suǒ xiū xíng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 420,
   "text": "一切诸佛之所显示，未来诸佛、菩萨摩诃萨亦复如是。",
   "pinyin": "yí qiè zhū fó zhī suǒ xiǎn shì wèi lái zhū fó pú sà mó hē sà yì fù rú shì",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 421,
   "text": "若佛、菩萨不由此门得一切智者，无有是处。",
   "pinyin": "ruò fó pú sà bù yóu cǐ mén dé yí qiè zhì zhě wú yǒu shì chù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 422,
   "text": "何以故？",
   "pinyin": "hé yǐ gù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 423,
   "text": "诸佛、菩萨无异路故。",
   "pinyin": "zhū fó pú sà wú yì lù gù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 424,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 425,
   "text": "若人闻此住忍、行忍、回向忍、欢喜忍、离垢忍、发光忍、焰慧忍、",
   "pinyin": "ruò rén wén cǐ zhù rěn xíng rěn huí xiàng rěn huān xǐ rěn lí gòu rěn fā guāng rěn yàn huì rěn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 426,
   "text": "难胜忍、现前忍、远行忍、不动忍、善慧忍、法云忍、正觉忍，",
   "pinyin": "nán shèng rěn xiàn qián rěn yuǎn xíng rěn bù dòng rěn shàn huì rěn fǎ yún rěn zhèng jué rěn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 427,
   "text": "能起一念清净信者，是人超过百劫、千劫、无量无边恒河沙劫一切苦难，",
   "pinyin": "néng qǐ yī niàn qīng jìng xìn zhě shì rén chāo guò bǎi jié qiān jié wú liàng wú biān héng hé shā jié yí qiè kǔ nàn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 428,
   "text": "不生恶趣，不久当得阿耨多罗三藐三菩提。",
   "pinyin": "bù shēng è qù bù jiǔ dāng dé ā nòu duō luó sān miǎo sān pú tí",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 429,
   "text": "是时十亿同名虚空藏菩萨摩诃萨，与无量无数诸来大众，",
   "pinyin": "shì shí shí yì tóng míng xū kōng zàng pú sà mó hē sà yǔ wú liàng wú shù zhū lái dà zhòng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 430,
   "text": "欢喜踊跃承佛威神，普见十方恒沙诸佛，各于道场说十四忍，",
   "pinyin": "huān xǐ yǒng yuè chéng fó wēi shén pǔ jiàn shí fāng héng shā zhū fó gè yú dào chǎng shuō shí sì rěn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 431,
   "text": "如我世尊所说无异，各各欢喜，如说修行般若波罗蜜多。",
   "pinyin": "rú wǒ shì zūn suǒ shuō wú yì gè gè huān xǐ rú shuō xiū xíng bō rě bō luó mì duō",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 432,
   "text": "尔时，世尊告波斯匿王：",
   "pinyin": "ěr shí shì zūn gào bō sī nì wáng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 433,
   "text": "汝先问云：",
   "pinyin": "rǔ xiān wèn yún",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 434,
   "text": "复以何相而住观察？",
   "pinyin": "fù yǐ hé xiàng ér zhù guān chá",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 435,
   "text": "菩萨摩诃萨应如是观：",
   "pinyin": "pú sà mó hē sà yīng rú shì guān",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 436,
   "text": "以幻化身而见幻化，正住平等无有彼我。",
   "pinyin": "yǐ huàn huà shēn ér jiàn huàn huà zhèng zhù píng děng wú yǒu bǐ wǒ",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 437,
   "text": "如是观察化利众生，然诸有情于久远劫，初刹那识异于木石，",
   "pinyin": "rú shì guān chá huà lì zhòng shēng rán zhū yǒu qíng yú jiǔ yuǎn jié chū chà nà shí yì yú mù shí",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 438,
   "text": "生得染净，各自能为无量无数染净识本。",
   "pinyin": "shēng dé rǎn jìng gè zì néng wéi wú liàng wú shù rǎn jìng shí běn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 439,
   "text": "从初刹那不可说劫，乃至金刚终一刹那，有不可说不可说识，",
   "pinyin": "cóng chū chà nà bù kě shuō jié nǎi zhì jīn gāng zhōng yī chà nà yǒu bù kě shuō bù kě shuō shí",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 440,
   "text": "生诸有情色、心二法——色名色蕴，心名四蕴——皆积聚性，隐覆真实。",
   "pinyin": "shēng zhū yǒu qíng sè xīn èr fǎ sè míng sè yùn xīn míng sì yùn jiē jī jù xìng yǐn fù zhēn shí",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 441,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 442,
   "text": "此一色法生无量色——眼得为色，耳得为声，鼻得为香，舌得为味，身得为触；",
   "pinyin": "cǐ yī sè fǎ shēng wú liàng sè yǎn dé wéi sè ěr dé wéi shēng bí dé wéi xiāng shé dé wéi wèi shēn dé wéi chù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 443,
   "text": "坚持名地，津润名水，暖性名火，轻动名风；",
   "pinyin": "jiān chí míng dì jīn rùn míng shuǐ nuǎn xìng míng huǒ qīng dòng míng fēng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 444,
   "text": "生五识处，名五色根。",
   "pinyin": "shēng wǔ shí chù míng wǔ sè gēn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 445,
   "text": "如是展转一色一心，生不可说无量色心，皆如幻故。",
   "pinyin": "rú shì zhǎn zhuǎn yī sè yī xīn shēng bù kě shuō wú liàng sè xīn jiē rú huàn gù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 446,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 447,
   "text": "有情之受，依世俗立，若有若无。",
   "pinyin": "yǒu qíng zhī shòu yī shì sú lì ruò yǒu ruò wú",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 448,
   "text": "但生有情妄想忆念，作业受果皆名世谛。",
   "pinyin": "dàn shēng yǒu qíng wàng xiǎng yì niàn zuò yè shòu guǒ jiē míng shì dì",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 449,
   "text": "三界六趣一切有情，婆罗门、刹帝利、毘舍、首陀，我人知见，色法心法如梦所见。",
   "pinyin": "sān jiè liù qù yí qiè yǒu qíng pó luó mén chà dì lì pí shě shǒu tuó wǒ rén zhī jiàn sè fǎ xīn fǎ rú mèng suǒ jiàn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 450,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 451,
   "text": "一切诸名，皆假施设。",
   "pinyin": "yí qiè zhū míng jiē jiǎ shī shè",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 452,
   "text": "佛未出前，世谛幻法，无名无义亦无体相；",
   "pinyin": "fó wèi chū qián shì dì huàn fǎ wú míng wú yì yì wú tǐ xiàng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 453,
   "text": "无三界名、善恶果报六趣名字；",
   "pinyin": "wú sān jiè míng shàn è guǒ bào liù qù míng zì",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 454,
   "text": "诸佛出现，为有情故，说于三界、六趣、染净无量名字。",
   "pinyin": "zhū fó chū xiàn wèi yǒu qíng gù shuō yú sān jiè liù qù rǎn jìng wú liàng míng zì",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 455,
   "text": "如是一切如呼声响，诸法相续念念不住，刹那刹那非一非异，",
   "pinyin": "rú shì yí qiè rú hū shēng xiǎng zhū fǎ xiāng xù niàn niàn bù zhù chà nà chà nà fēi yī fēi yì",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 456,
   "text": "速起速灭非断非常，诸有为法如阳焰故，诸法相待，所谓色界、眼界、眼识界，",
   "pinyin": "sù qǐ sù miè fēi duàn fēi cháng zhū yǒu wéi fǎ rú yáng yàn gù zhū fǎ xiāng dài suǒ wèi sè jiè yǎn jiè yǎn shí jiè",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 457,
   "text": "乃至法界、意界、意识界，犹如电光不定相待，有无一异，如第二月，诸法缘成；",
   "pinyin": "nǎi zhì fǎ jiè yì jiè yì shí jiè yóu rú diàn guāng bù dìng xiāng dài yǒu wú yī yì rú dì èr yuè zhū fǎ yuán chéng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 458,
   "text": "蕴、处、界法如水上泡，诸法因成。",
   "pinyin": "yùn chù jiè fǎ rú shuǐ shàng pào zhū fǎ yīn chéng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 459,
   "text": "一切有情，俱时因果、异时因果，三世善恶如空中云。",
   "pinyin": "yí qiè yǒu qíng jù shí yīn guǒ yì shí yīn guǒ sān shì shàn è rú kōng zhōng yún",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 460,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 461,
   "text": "菩萨摩诃萨住无分别，无彼此相，无自他相，常行化利无化利相。",
   "pinyin": "pú sà mó hē sà zhù wú fēn bié wú bǐ cǐ xiàng wú zì tā xiàng cháng xíng huà lì wú huà lì xiàng",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 462,
   "text": "是故应知，愚夫垢识，染著虚妄为相所缚；",
   "pinyin": "shì gù yīng zhī yú fū gòu shí rǎn zhuó xū wàng wéi xiàng suǒ fù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 463,
   "text": "菩萨照见，知如幻士，无有体相但如空花，",
   "pinyin": "pú sà zhào jiàn zhī rú huàn shì wú yǒu tǐ xiàng dàn rú kōng huā",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 464,
   "text": "是为菩萨摩诃萨住利自他如实观察。",
   "pinyin": "shì wéi pú sà mó hē sà zhù lì zì tā rú shí guān chá",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 465,
   "text": "说是法时，会中无量人、天大众，有得伏忍、空无生忍，",
   "pinyin": "shuō shì fǎ shí huì zhōng wú liàng rén tiān dà zhòng yǒu dé fú rěn kōng wú shēng rěn",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 466,
   "text": "一地、二地乃至十地，无量菩萨得一生补处。",
   "pinyin": "yī dì èr dì nǎi zhì shí dì wú liàng pú sà dé yī shēng bǔ chù",
   "part": "长行",
   "heading": "菩萨行品第三"
  },
  {
   "n": 467,
   "text": "尔时，波斯匿王白佛言：",
   "pinyin": "ěr shí bō sī nì wáng bái fó yán",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 468,
   "text": "世尊！",
   "pinyin": "shì zūn",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 469,
   "text": "胜义谛中有世俗谛不？",
   "pinyin": "shèng yì dì zhōng yǒu shì sú dì bù",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 470,
   "text": "若言无者，智不应二；",
   "pinyin": "ruò yán wú zhě zhì bù yīng èr",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 471,
   "text": "若言有者；",
   "pinyin": "ruò yán yǒu zhě",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 472,
   "text": "智不应一。",
   "pinyin": "zhì bù yīng yī",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 473,
   "text": "一二之义，其事云何？",
   "pinyin": "yī èr zhī yì qí shì yún hé",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 474,
   "text": "佛言：",
   "pinyin": "fó yán",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 475,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 476,
   "text": "汝于过去龙光王佛法中已问此义，我今无说，",
   "pinyin": "rǔ yú guò qù lóng guāng wáng fó fǎ zhōng yǐ wèn cǐ yì wǒ jīn wú shuō",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 477,
   "text": "汝今无听，无说无听是即名为一义二义。",
   "pinyin": "rǔ jīn wú tīng wú shuō wú tīng shì jí míng wéi yī yì èr yì",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 478,
   "text": "汝今谛听，当为汝说。",
   "pinyin": "rǔ jīn dì tīng dāng wèi rǔ shuō",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 479,
   "text": "尔时，世尊即说偈言：",
   "pinyin": "ěr shí shì zūn jí shuō jì yán",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 480,
   "text": "无相胜义谛，",
   "pinyin": "wú xiàng shèng yì dì",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 481,
   "text": "体非自他作，",
   "pinyin": "tǐ fēi zì tā zuò",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 482,
   "text": "因缘如幻有，",
   "pinyin": "yīn yuán rú huàn yǒu",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 483,
   "text": "亦非自他作。",
   "pinyin": "yì fēi zì tā zuò",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 484,
   "text": "法性本无性。",
   "pinyin": "fǎ xìng běn wú xìng",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 485,
   "text": "胜义谛空如。",
   "pinyin": "shèng yì dì kōng rú",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 486,
   "text": "诸有幻有法。",
   "pinyin": "zhū yǒu huàn yǒu fǎ",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 487,
   "text": "三假集假有。",
   "pinyin": "sān jiǎ jí jiǎ yǒu",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 488,
   "text": "无无谛实无，",
   "pinyin": "wú wú dì shí wú",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 489,
   "text": "寂灭胜义空，",
   "pinyin": "jì miè shèng yì kōng",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 490,
   "text": "诸法因缘有，",
   "pinyin": "zhū fǎ yīn yuán yǒu",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 491,
   "text": "有无义如是，",
   "pinyin": "yǒu wú yì rú shì",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 492,
   "text": "有无本自二，",
   "pinyin": "yǒu wú běn zì èr",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 493,
   "text": "譬如牛二角，",
   "pinyin": "pì rú niú èr jiǎo",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 494,
   "text": "照解见无二，",
   "pinyin": "zhào jiě jiàn wú èr",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 495,
   "text": "二谛常不即。",
   "pinyin": "èr dì cháng bù jí",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 496,
   "text": "解心见无二，",
   "pinyin": "jiě xīn jiàn wú èr",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 497,
   "text": "求二不可得，",
   "pinyin": "qiú èr bù kě dé",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 498,
   "text": "非谓二谛一，",
   "pinyin": "fēi wèi èr dì yī",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 499,
   "text": "一亦不可得，",
   "pinyin": "yī yì bù kě dé",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 500,
   "text": "于解常自一，",
   "pinyin": "yú jiě cháng zì yī",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 501,
   "text": "于谛常自二，",
   "pinyin": "yú dì cháng zì èr",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 502,
   "text": "了达此一二，",
   "pinyin": "liǎo dá cǐ yī èr",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 503,
   "text": "真入胜义谛。",
   "pinyin": "zhēn rù shèng yì dì",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 504,
   "text": "世谛幻化起，",
   "pinyin": "shì dì huàn huà qǐ",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 505,
   "text": "譬如虚空花，",
   "pinyin": "pì rú xū kōng huā",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 506,
   "text": "如影如毛轮，",
   "pinyin": "rú yǐng rú máo lún",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 507,
   "text": "因缘故幻有。",
   "pinyin": "yīn yuán gù huàn yǒu",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 508,
   "text": "幻化见幻化，",
   "pinyin": "huàn huà jiàn huàn huà",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 509,
   "text": "愚夫名幻谛，",
   "pinyin": "yú fū míng huàn dì",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 510,
   "text": "幻师见幻法，",
   "pinyin": "huàn shī jiàn huàn fǎ",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 511,
   "text": "谛幻悉皆无。",
   "pinyin": "dì huàn xī jiē wú",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 512,
   "text": "若了如是法，",
   "pinyin": "ruò liǎo rú shì fǎ",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 513,
   "text": "即解一二义，",
   "pinyin": "jí jiě yī èr yì",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 514,
   "text": "遍于一切法，",
   "pinyin": "biàn yú yí qiè fǎ",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 515,
   "text": "应作如是观。",
   "pinyin": "yīng zuò rú shì guān",
   "part": "偈颂",
   "heading": "二谛品第四"
  },
  {
   "n": 516,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 517,
   "text": "菩萨摩诃萨住胜义谛化诸有情，佛及有情一而无二。",
   "pinyin": "pú sà mó hē sà zhù shèng yì dì huà zhū yǒu qíng fó jí yǒu qíng yī ér wú èr",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 518,
   "text": "何以故？",
   "pinyin": "hé yǐ gù",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 519,
   "text": "有情、菩提此二皆空。",
   "pinyin": "yǒu qíng pú tí cǐ èr jiē kōng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 520,
   "text": "以有情空得置菩提空，以菩提空得置有情空，以一切法空空故空。",
   "pinyin": "yǐ yǒu qíng kōng dé zhì pú tí kōng yǐ pú tí kōng dé zhì yǒu qíng kōng yǐ yí qiè fǎ kōng kōng gù kōng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 521,
   "text": "何以故？",
   "pinyin": "hé yǐ gù",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 522,
   "text": "般若无相，二谛皆空，谓从无明至一切智，无自相无他相，",
   "pinyin": "bō rě wú xiàng èr dì jiē kōng wèi cóng wú míng zhì yí qiè zhì wú zì xiàng wú tā xiàng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 523,
   "text": "于第一义见无所见，若有修行亦不取著，若不修行亦不取著，",
   "pinyin": "yú dì yī yì jiàn wú suǒ jiàn ruò yǒu xiū xíng yì bù qǔ zhuó ruò bù xiū xíng yì bù qǔ zhuó",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 524,
   "text": "非行非不行亦不取著，于一切法皆不取著。",
   "pinyin": "fēi xíng fēi bù xíng yì bù qǔ zhuó yú yí qiè fǎ jiē bù qǔ zhuó",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 525,
   "text": "菩萨未成佛，以菩提为烦恼；",
   "pinyin": "pú sà wèi chéng fó yǐ pú tí wéi fán nǎo",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 526,
   "text": "菩萨成佛时，以烦恼为菩提。",
   "pinyin": "pú sà chéng fó shí yǐ fán nǎo wéi pú tí",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 527,
   "text": "何以故？",
   "pinyin": "hé yǐ gù",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 528,
   "text": "于第一义而无二故，诸佛如来与一切法悉皆如故。",
   "pinyin": "yú dì yī yì ér wú èr gù zhū fó rú lái yǔ yí qiè fǎ xī jiē rú gù",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 529,
   "text": "波斯匿王白佛言：",
   "pinyin": "bō sī nì wáng bái fó yán",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 530,
   "text": "十方诸佛、一切菩萨，云何不离文字而行实相？",
   "pinyin": "shí fāng zhū fó yí qiè pú sà yún hé bù lí wén zì ér xíng shí xiàng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 531,
   "text": "佛言：",
   "pinyin": "fó yán",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 532,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 533,
   "text": "文字者，谓契经、应颂、记别、讽诵、自说、缘起、譬喻、本事、本生、方广、希有、论议，",
   "pinyin": "wén zì zhě wèi qì jīng yìng sòng jì bié fěng sòng zì shuō yuán qǐ pì yù běn shì běn shēng fāng guǎng xī yǒu lùn yì",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 534,
   "text": "所有宣说音声，语言，文字，章句，一切皆如，无非实相；",
   "pinyin": "suǒ yǒu xuān shuō yīn shēng yǔ yán wén zì zhāng jù yí qiè jiē rú wú fēi shí xiàng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 535,
   "text": "若取文字相者，即非实相。",
   "pinyin": "ruò qǔ wén zì xiàng zhě jí fēi shí xiàng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 536,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 537,
   "text": "修实相者，如文字修。",
   "pinyin": "xiū shí xiàng zhě rú wén zì xiū",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 538,
   "text": "实相即是诸佛智母，一切有情根本智母，此即名为一切智体。",
   "pinyin": "shí xiàng jí shì zhū fó zhì mǔ yí qiè yǒu qíng gēn běn zhì mǔ cǐ jí míng wéi yí qiè zhì tǐ",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 539,
   "text": "诸佛未成佛，与当佛为智母；",
   "pinyin": "zhū fó wèi chéng fó yǔ dāng fó wéi zhì mǔ",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 540,
   "text": "诸佛已成佛，即为一切智。",
   "pinyin": "zhū fó yǐ chéng fó jí wéi yí qiè zhì",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 541,
   "text": "未得为性，已得为智。",
   "pinyin": "wèi dé wéi xìng yǐ dé wéi zhì",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 542,
   "text": "三乘般若，不生不灭，自性常住。",
   "pinyin": "sān shèng bō rě bù shēng bù miè zì xìng cháng zhù",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 543,
   "text": "一切有情，此为觉性。",
   "pinyin": "yí qiè yǒu qíng cǐ wéi jué xìng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 544,
   "text": "若菩萨不著文字、不离文字，无文字相非无文字，能如是修不见修相，",
   "pinyin": "ruò pú sà bù zhuó wén zì bù lí wén zì wú wén zì xiàng fēi wú wén zì néng rú shì xiū bù jiàn xiū xiàng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 545,
   "text": "是即名为修文字者，而能得于般若真性，是为般若波罗蜜多。",
   "pinyin": "shì jí míng wéi xiū wén zì zhě ér néng dé yú bō rě zhēn xìng shì wéi bō rě bō luó mì duō",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 546,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 547,
   "text": "菩萨摩诃萨护佛果、护十地行、护化有情，为若此也。",
   "pinyin": "pú sà mó hē sà hù fó guǒ hù shí dì xíng hù huà yǒu qíng wéi ruò cǐ yě",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 548,
   "text": "波斯匿王白佛言：",
   "pinyin": "bō sī nì wáng bái fó yán",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 549,
   "text": "真性是一，有情品类根行无量，法门为一、为无量耶？",
   "pinyin": "zhēn xìng shì yī yǒu qíng pǐn lèi gēn xíng wú liàng fǎ mén wéi yī wéi wú liàng yé",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 550,
   "text": "佛言：",
   "pinyin": "fó yán",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 551,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 552,
   "text": "法门非一亦非无量。",
   "pinyin": "fǎ mén fēi yī yì fēi wú liàng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 553,
   "text": "何以故？",
   "pinyin": "hé yǐ gù",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 554,
   "text": "由诸有情色法、心法，五取蕴相、我人知见，",
   "pinyin": "yóu zhū yǒu qíng sè fǎ xīn fǎ wǔ qǔ yùn xiàng wǒ rén zhī jiàn",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 555,
   "text": "种种根行品类无边，法门随根亦有无量。",
   "pinyin": "zhǒng zhǒng gēn xíng pǐn lèi wú biān fǎ mén suí gēn yì yǒu wú liàng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 556,
   "text": "此诸法性，非相非无相而非无量。",
   "pinyin": "cǐ zhū fǎ xìng fēi xiàng fēi wú xiàng ér fēi wú liàng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 557,
   "text": "若菩萨随诸有情见一见二，",
   "pinyin": "ruò pú sà suí zhū yǒu qíng jiàn yī jiàn èr",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 558,
   "text": "是即不见一二之义——了知一二非一非二，即胜义谛；",
   "pinyin": "shì jí bù jiàn yī èr zhī yì liǎo zhī yī èr fēi yī fēi èr jí shèng yì dì",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 559,
   "text": "取著一二若有若无，即世俗谛——是故法门非一非二。",
   "pinyin": "qǔ zhuó yī èr ruò yǒu ruò wú jí shì sú dì shì gù fǎ mén fēi yī fēi èr",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 560,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 561,
   "text": "一切诸佛说般若波罗蜜多，我今说般若波罗蜜多无二无别。",
   "pinyin": "yí qiè zhū fó shuō bō rě bō luó mì duō wǒ jīn shuō bō rě bō luó mì duō wú èr wú bié",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 562,
   "text": "汝等大众，受持、读诵、如说修行，即为受持诸佛之法。",
   "pinyin": "rǔ děng dà zhòng shòu chí dú sòng rú shuō xiū xíng jí wéi shòu chí zhū fó zhī fǎ",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 563,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 564,
   "text": "此般若波罗蜜多功德无量，若有恒河沙不可说诸佛，",
   "pinyin": "cǐ bō rě bō luó mì duō gōng dé wú liàng ruò yǒu héng hé shā bù kě shuō zhū fó",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 565,
   "text": "是一一佛教化无量不可说有情，是一一有情皆得成佛，",
   "pinyin": "shì yī yī fó jiào huà wú liàng bù kě shuō yǒu qíng shì yī yī yǒu qíng jiē dé chéng fó",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 566,
   "text": "是诸佛等复教化无量不可说有情亦皆成佛，",
   "pinyin": "shì zhū fó děng fù jiào huà wú liàng bù kě shuō yǒu qíng yì jiē chéng fó",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 567,
   "text": "是诸佛等所说般若波罗蜜多，有无量不可说那庾多亿偈，说不可尽。",
   "pinyin": "shì zhū fó děng suǒ shuō bō rě bō luó mì duō yǒu wú liàng bù kě shuō nà yǔ duō yì jì shuō bù kě jìn",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 568,
   "text": "于诸偈中而取一偈分为千分，复于千分而说一分，",
   "pinyin": "yú zhū jì zhōng ér qǔ yī jì fēn wéi qiān fēn fù yú qiān fēn ér shuō yī fēn",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 569,
   "text": "句义功德尚无穷尽，何况如是无量句义所有功德。",
   "pinyin": "jù yì gōng dé shàng wú qióng jìn hé kuàng rú shì wú liàng jù yì suǒ yǒu gōng dé",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 570,
   "text": "若有人能于此经中起一念净信，是人即超百劫、千劫、百千万劫生死苦难，",
   "pinyin": "ruò yǒu rén néng yú cǐ jīng zhōng qǐ yī niàn jìng xìn shì rén jí chāo bǎi jié qiān jié bǎi qiān wàn jié shēng sǐ kǔ nàn",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 571,
   "text": "何况书写、受持、读诵、为人解说所得功德，即与十方一切诸佛等无有异。",
   "pinyin": "hé kuàng shū xiě shòu chí dú sòng wèi rén jiě shuō suǒ dé gōng dé jí yǔ shí fāng yí qiè zhū fó děng wú yǒu yì",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 572,
   "text": "当知此人，诸佛护念，不久当成阿耨多罗三藐三菩提。",
   "pinyin": "dāng zhī cǐ rén zhū fó hù niàn bù jiǔ dāng chéng ā nòu duō luó sān miǎo sān pú tí",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 573,
   "text": "说是法时，有十亿人得三空忍，百万亿人得大空忍，无量菩萨得住十地。",
   "pinyin": "shuō shì fǎ shí yǒu shí yì rén dé sān kōng rěn bǎi wàn yì rén dé dà kōng rěn wú liàng pú sà dé zhù shí dì",
   "part": "长行",
   "heading": "二谛品第四"
  },
  {
   "n": 574,
   "text": "尔时，世尊告波斯匿王等诸大国王：",
   "pinyin": "ěr shí shì zūn gào bō sī nì wáng děng zhū dà guó wáng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 575,
   "text": "谛听，谛听！",
   "pinyin": "dì tīng dì tīng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 576,
   "text": "我为汝等说护国法。",
   "pinyin": "wǒ wèi rǔ děng shuō hù guó fǎ",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 577,
   "text": "一切国土若欲乱时，有诸灾难，贼来破坏。",
   "pinyin": "yí qiè guó tǔ ruò yù luàn shí yǒu zhū zāi nàn zéi lái pò huài",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 578,
   "text": "汝等诸王，应当受持，读诵此般若波罗蜜多，严饰道场，",
   "pinyin": "rǔ děng zhū wáng yīng dāng shòu chí dú sòng cǐ bō rě bō luó mì duō yán shì dào chǎng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 579,
   "text": "置百佛像、百菩萨像、百师子座，请百法师解说此经。",
   "pinyin": "zhì bǎi fó xiàng bǎi pú sà xiàng bǎi shī zǐ zuò qǐng bǎi fǎ shī jiě shuō cǐ jīng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 580,
   "text": "于诸座前燃种种灯，烧种种香，散诸杂花，",
   "pinyin": "yú zhū zuò qián rán zhǒng zhǒng dēng shāo zhǒng zhǒng xiāng sàn zhū zá huā",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 581,
   "text": "广大供养衣服、卧具、饮食、汤药、房舍、床座一切供事；",
   "pinyin": "guǎng dà gòng yǎng yī fú wò jù yǐn shí tāng yào fáng shè chuáng zuò yí qiè gòng shì",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 582,
   "text": "每日二时讲读此经。",
   "pinyin": "měi rì èr shí jiǎng dú cǐ jīng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 583,
   "text": "若王、大臣，比丘、比丘尼、优婆塞、优婆夷，听受、读诵、如法修行，灾难即灭。",
   "pinyin": "ruò wáng dà chén bǐ qiū bǐ qiū ní yōu pó sāi yōu pó yí tīng shòu dú sòng rú fǎ xiū xíng zāi nàn jí miè",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 584,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 585,
   "text": "诸国土中有无量鬼神，一一复有无量眷属，若闻是经，护汝国土。",
   "pinyin": "zhū guó tǔ zhōng yǒu wú liàng guǐ shén yī yī fù yǒu wú liàng juàn shǔ ruò wén shì jīng hù rǔ guó tǔ",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 586,
   "text": "若国欲乱，鬼神先乱；",
   "pinyin": "ruò guó yù luàn guǐ shén xiān luàn",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 587,
   "text": "鬼神乱故，即万人乱——当有贼起，百姓丧亡；",
   "pinyin": "guǐ shén luàn gù jí wàn rén luàn dāng yǒu zéi qǐ bǎi xìng sàng wáng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 588,
   "text": "国王、大子、王子、百官互相是非。",
   "pinyin": "guó wáng dà zǐ wáng zǐ bǎi guān hù xiāng shì fēi",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 589,
   "text": "天地变怪，日月众星失时失度，大火、大水及大风等，",
   "pinyin": "tiān dì biàn guài rì yuè zhòng xīng shī shí shī dù dà huǒ dà shuǐ jí dà fēng děng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 590,
   "text": "是诸难起，皆应受持、讲说此般若波罗蜜多。",
   "pinyin": "shì zhū nàn qǐ jiē yīng shòu chí jiǎng shuō cǐ bō rě bō luó mì duō",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 591,
   "text": "若于是经受持、读诵，",
   "pinyin": "ruò yú shì jīng shòu chí dú sòng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 592,
   "text": "一切所求——官位、富饶、男女、慧解、行来随意、人天果报——皆得满足；",
   "pinyin": "yí qiè suǒ qiú guān wèi fù ráo nán nǚ huì jiě xíng lái suí yì rén tiān guǒ bào jiē dé mǎn zú",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 593,
   "text": "疾疫厄难即得除愈；",
   "pinyin": "jí yì è nàn jí dé chú yù",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 594,
   "text": "杻械枷锁捡系其身皆得解脱；",
   "pinyin": "chǒu xiè jiā suǒ jiǎn xì qí shēn jiē dé jiě tuō",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 595,
   "text": "破四重戒、作五逆罪及毁诸戒无量过咎悉得消灭。",
   "pinyin": "pò sì zhòng jiè zuò wǔ nì zuì jí huǐ zhū jiè wú liàng guò jiù xī dé xiāo miè",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 596,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 597,
   "text": "往昔过去释提桓因为顶生王，领四军众来上天宫欲灭帝释。",
   "pinyin": "wǎng xī guò qù shì tí huán yīn wéi dǐng shēng wáng lǐng sì jūn zhòng lái shàng tiān gōng yù miè dì shì",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 598,
   "text": "时彼天主即依过去诸佛教法，敷百高座，请百法师讲读般若波罗蜜多经。",
   "pinyin": "shí bǐ tiān zhǔ jí yī guò qù zhū fó jiào fǎ fū bǎi gāo zuò qǐng bǎi fǎ shī jiǎng dú bō rě bō luó mì duō jīng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 599,
   "text": "顶生即退，天众安乐。",
   "pinyin": "dǐng shēng jí tuì tiān zhòng ān lè",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 600,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 601,
   "text": "昔天罗国王，有一太子名曰斑足，登王位时，有外道师名为善施，",
   "pinyin": "xī tiān luó guó wáng yǒu yī tài zǐ míng yuē bān zú dēng wáng wèi shí yǒu wài dào shī míng wéi shàn shī",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 602,
   "text": "与王灌顶，乃令斑足取千王头，以祀冢间摩诃迦罗大黑天神。",
   "pinyin": "yǔ wáng guàn dǐng nǎi lìng bān zú qǔ qiān wáng tóu yǐ sì zhǒng jiān mó hē jiā luó dà hēi tiān shén",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 603,
   "text": "自登王位，已得九百九十九王，唯少一王。",
   "pinyin": "zì dēng wáng wèi yǐ dé jiǔ bǎi jiǔ shí jiǔ wáng wéi shǎo yī wáng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 604,
   "text": "北行万里，乃得一王名曰普明。",
   "pinyin": "běi xíng wàn lǐ nǎi dé yī wáng míng yuē pǔ míng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 605,
   "text": "其普明王白斑足言：",
   "pinyin": "qí pǔ míng wáng bái bān zú yán",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 606,
   "text": "愿听一日礼敬三宝、饭食沙门。",
   "pinyin": "yuàn tīng yī rì lǐ jìng sān bǎo fàn shí shā mén",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 607,
   "text": "斑足闻已即便许之。",
   "pinyin": "bān zú wén yǐ jí biàn xǔ zhī",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 608,
   "text": "其王乃依过去诸佛所说教法，敷百高座，请百法师，",
   "pinyin": "qí wáng nǎi yī guò qù zhū fó suǒ shuō jiào fǎ fū bǎi gāo zuò qǐng bǎi fǎ shī",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 609,
   "text": "一日二时讲说般若波罗蜜多八千亿偈。",
   "pinyin": "yī rì èr shí jiǎng shuō bō rě bō luó mì duō bā qiān yì jì",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 610,
   "text": "时彼众中第一法师，为普明王而说偈言：",
   "pinyin": "shí bǐ zhòng zhōng dì yī fǎ shī wèi pǔ míng wáng ér shuō jì yán",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 611,
   "text": "劫火洞然，",
   "pinyin": "jié huǒ dòng rán",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 612,
   "text": "大千俱坏，",
   "pinyin": "dà qiān jù huài",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 613,
   "text": "须弥巨海，",
   "pinyin": "xū mí jù hǎi",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 614,
   "text": "磨灭无余。",
   "pinyin": "mó miè wú yú",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 615,
   "text": "梵释天龙，",
   "pinyin": "fàn shì tiān lóng",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 616,
   "text": "诸有情等，",
   "pinyin": "zhū yǒu qíng děng",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 617,
   "text": "尚皆殄灭，",
   "pinyin": "shàng jiē tiǎn miè",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 618,
   "text": "何况此身。",
   "pinyin": "hé kuàng cǐ shēn",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 619,
   "text": "生老病死，",
   "pinyin": "shēng lǎo bìng sǐ",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 620,
   "text": "忧悲苦恼，",
   "pinyin": "yōu bēi kǔ nǎo",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 621,
   "text": "怨亲逼迫，",
   "pinyin": "yuàn qīn bī pò",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 622,
   "text": "能与愿违。",
   "pinyin": "néng yǔ yuàn wéi",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 623,
   "text": "爱欲结使，",
   "pinyin": "ài yù jié shǐ",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 624,
   "text": "自作疮疣，",
   "pinyin": "zì zuò chuāng yóu",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 625,
   "text": "三界无安，",
   "pinyin": "sān jiè wú ān",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 626,
   "text": "国有何乐？",
   "pinyin": "guó yǒu hé lè",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 627,
   "text": "有为不实，",
   "pinyin": "yǒu wéi bù shí",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 628,
   "text": "从因缘起，",
   "pinyin": "cóng yīn yuán qǐ",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 629,
   "text": "盛衰电转，",
   "pinyin": "shèng shuāi diàn zhuǎn",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 630,
   "text": "暂有即无。",
   "pinyin": "zàn yǒu jí wú",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 631,
   "text": "诸界趣生，",
   "pinyin": "zhū jiè qù shēng",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 632,
   "text": "随业缘现，",
   "pinyin": "suí yè yuán xiàn",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 633,
   "text": "如影如响，",
   "pinyin": "rú yǐng rú xiǎng",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 634,
   "text": "一切皆空。",
   "pinyin": "yí qiè jiē kōng",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 635,
   "text": "识由业漂，",
   "pinyin": "shí yóu yè piāo",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 636,
   "text": "乘四大起，",
   "pinyin": "chéng sì dà qǐ",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 637,
   "text": "无明爱缚，",
   "pinyin": "wú míng ài fù",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 638,
   "text": "我我所生。",
   "pinyin": "wǒ wǒ suǒ shēng",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 639,
   "text": "识随业迁，",
   "pinyin": "shí suí yè qiān",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 640,
   "text": "身即无主；",
   "pinyin": "shēn jí wú zhǔ",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 641,
   "text": "应知国土，",
   "pinyin": "yīng zhī guó tǔ",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 642,
   "text": "幻化亦然。",
   "pinyin": "huàn huà yì rán",
   "part": "偈颂",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 643,
   "text": "尔时法师说此偈已，时普明王闻法悟解，证空三昧，王诸眷属得法眼空。",
   "pinyin": "ěr shí fǎ shī shuō cǐ jì yǐ shí pǔ míng wáng wén fǎ wù jiě zhèng kōng sān mèi wáng zhū juàn shǔ dé fǎ yǎn kōng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 644,
   "text": "其王即便诣天罗国，诸王众中而作是言：",
   "pinyin": "qí wáng jí biàn yì tiān luó guó zhū wáng zhòng zhōng ér zuò shì yán",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 645,
   "text": "仁等！",
   "pinyin": "rén děng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 646,
   "text": "今者就命时到。",
   "pinyin": "jīn zhě jiù mìng shí dào",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 647,
   "text": "悉应诵持过去诸佛所说般若波罗蜜多偈。",
   "pinyin": "xī yīng sòng chí guò qù zhū fó suǒ shuō bō rě bō luó mì duō jì",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 648,
   "text": "诸王闻已亦皆悟解，得空三昧，各各诵持。",
   "pinyin": "zhū wáng wén yǐ yì jiē wù jiě dé kōng sān mèi gè gè sòng chí",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 649,
   "text": "时斑足王问诸王言：",
   "pinyin": "shí bān zú wáng wèn zhū wáng yán",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 650,
   "text": "汝等今者皆诵何法？",
   "pinyin": "rǔ děng jīn zhě jiē sòng hé fǎ",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 651,
   "text": "尔时普明即以上偈答斑足王，王闻是法亦证空定，欢喜踊跃告诸王言：",
   "pinyin": "ěr shí pǔ míng jí yǐ shàng jì dá bān zú wáng wáng wén shì fǎ yì zhèng kōng dìng huān xǐ yǒng yuè gào zhū wáng yán",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 652,
   "text": "我为外道邪师所误，非汝等咎；",
   "pinyin": "wǒ wéi wài dào xié shī suǒ wù fēi rǔ děng jiù",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 653,
   "text": "汝各还国，当请法师解说般若波罗蜜多。",
   "pinyin": "rǔ gè huán guó dāng qǐng fǎ shī jiě shuō bō rě bō luó mì duō",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 654,
   "text": "时斑足王以国付弟，出家为道，得无生法忍。",
   "pinyin": "shí bān zú wáng yǐ guó fù dì chū jiā wéi dào dé wú shēng fǎ rěn",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 655,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 656,
   "text": "过去复有五千国王常诵此经，现生获报；",
   "pinyin": "guò qù fù yǒu wǔ qiān guó wáng cháng sòng cǐ jīng xiàn shēng huò bào",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 657,
   "text": "汝等十六诸大国王，修护国法，应当如是受持、读诵、解说此经；",
   "pinyin": "rǔ děng shí liù zhū dà guó wáng xiū hù guó fǎ yīng dāng rú shì shòu chí dú sòng jiě shuō cǐ jīng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 658,
   "text": "若未来世诸国王等，为欲护国护自身者，亦应如是受持、读诵、解说此经。",
   "pinyin": "ruò wèi lái shì zhū guó wáng děng wèi yù hù guó hù zì shēn zhě yì yīng rú shì shòu chí dú sòng jiě shuō cǐ jīng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 659,
   "text": "说是法时，无量人众得不退转，阿修罗等得生天上，",
   "pinyin": "shuō shì fǎ shí wú liàng rén zhòng dé bù tuì zhuǎn ā xiū luó děng dé shēng tiān shàng",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 660,
   "text": "无量无数欲、色诸天得无生忍。",
   "pinyin": "wú liàng wú shù yù sè zhū tiān dé wú shēng rěn",
   "part": "长行",
   "heading": "卷下　护国品第五"
  },
  {
   "n": 661,
   "text": "尔时十六国王及诸大众，闻佛说此般若波罗蜜多甚深句义，",
   "pinyin": "ěr shí shí liù guó wáng jí zhū dà zhòng wén fó shuō cǐ bō rě bō luó mì duō shèn shēn jù yì",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 662,
   "text": "欢喜踊跃，散百万亿众宝莲花，于虚空中成宝花座；",
   "pinyin": "huān xǐ yǒng yuè sàn bǎi wàn yì zhòng bǎo lián huā yú xū kōng zhōng chéng bǎo huā zuò",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 663,
   "text": "十方诸佛无量大众，共坐此座，说般若波罗蜜多。",
   "pinyin": "shí fāng zhū fó wú liàng dà zhòng gòng zuò cǐ zuò shuō bō rě bō luó mì duō",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 664,
   "text": "是诸大众持十千金莲华，散释迦牟尼佛上，合成花轮盖诸大众；",
   "pinyin": "shì zhū dà zhòng chí shí qiān jīn lián huá sàn shì jiā móu ní fó shàng hé chéng huā lún gài zhū dà zhòng",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 665,
   "text": "复散八万四千芬陀利花，于虚空中成白云台，",
   "pinyin": "fù sàn bā wàn sì qiān fēn tuó lì huā yú xū kōng zhōng chéng bái yún tái",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 666,
   "text": "台中光明王佛与十方诸佛、无量大众，演说般若波罗蜜多。",
   "pinyin": "tái zhōng guāng míng wáng fó yǔ shí fāng zhū fó wú liàng dà zhòng yǎn shuō bō rě bō luó mì duō",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 667,
   "text": "是诸大众，持曼陀罗花，散释迦牟尼佛及诸众会；",
   "pinyin": "shì zhū dà zhòng chí màn tuó luó huā sàn shì jiā móu ní fó jí zhū zhòng huì",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 668,
   "text": "复散曼殊沙花，于虚空中变作金刚宝城，",
   "pinyin": "fù sàn màn shū shā huā yú xū kōng zhōng biàn zuò jīn gāng bǎo chéng",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 669,
   "text": "城中师子奋迅王佛共十方诸佛、大菩萨众，演说胜义般若波罗蜜多。",
   "pinyin": "chéng zhōng shī zǐ fèn xùn wáng fó gòng shí fāng zhū fó dà pú sà zhòng yǎn shuō shèng yì bō rě bō luó mì duō",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 670,
   "text": "复散无量天诸妙花，于虚空中成宝云盖，",
   "pinyin": "fù sàn wú liàng tiān zhū miào huā yú xū kōng zhōng chéng bǎo yún gài",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 671,
   "text": "遍覆三千大千世界，是花盖中雨恒河沙花，从空而下。",
   "pinyin": "biàn fù sān qiān dà qiān shì jiè shì huā gài zhōng yǔ héng hé shā huā cóng kōng ér xià",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 672,
   "text": "时波斯匿王及诸大众，见是事已叹未曾有，合掌向佛而作是言：",
   "pinyin": "shí bō sī nì wáng jí zhū dà zhòng jiàn shì shì yǐ tàn wèi céng yǒu hé zhǎng xiàng fó ér zuò shì yán",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 673,
   "text": "愿过去、现在、未来诸佛，常说般若波罗蜜多；",
   "pinyin": "yuàn guò qù xiàn zài wèi lái zhū fó cháng shuō bō rě bō luó mì duō",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 674,
   "text": "愿诸众生常得见闻，如我今日等无有异。",
   "pinyin": "yuàn zhū zhòng shēng cháng dé jiàn wén rú wǒ jīn rì děng wú yǒu yì",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 675,
   "text": "佛言：",
   "pinyin": "fó yán",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 676,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 677,
   "text": "如汝所说。",
   "pinyin": "rú rǔ suǒ shuō",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 678,
   "text": "此般若波罗蜜多，是诸佛母、诸菩萨母，不共功德神通生处，",
   "pinyin": "cǐ bō rě bō luó mì duō shì zhū fó mǔ zhū pú sà mǔ bù gòng gōng dé shén tōng shēng chù",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 679,
   "text": "诸佛同说能多利益，是故汝等常应受持。",
   "pinyin": "zhū fó tóng shuō néng duō lì yì shì gù rǔ děng cháng yīng shòu chí",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 680,
   "text": "尔时，世尊为诸大众现不可思议神通变化——一花入无量花，无量花入一花；",
   "pinyin": "ěr shí shì zūn wèi zhū dà zhòng xiàn bù kě sī yì shén tōng biàn huà yī huā rù wú liàng huā wú liàng huā rù yī huā",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 681,
   "text": "一佛土入无量佛土，无量佛土入一佛土；",
   "pinyin": "yī fó tǔ rù wú liàng fó tǔ wú liàng fó tǔ rù yī fó tǔ",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 682,
   "text": "一尘刹土入无量尘刹土，无量尘刹土入一尘刹土；",
   "pinyin": "yī chén chà tǔ rù wú liàng chén chà tǔ wú liàng chén chà tǔ rù yī chén chà tǔ",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 683,
   "text": "无量大海入一毛孔；",
   "pinyin": "wú liàng dà hǎi rù yī máo kǒng",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 684,
   "text": "无量须弥入芥子中；",
   "pinyin": "wú liàng xū mí rù jiè zǐ zhōng",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 685,
   "text": "一佛身入无量众生身，无量众生身入一佛身；",
   "pinyin": "yī fó shēn rù wú liàng zhòng shēng shēn wú liàng zhòng shēng shēn rù yī fó shēn",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 686,
   "text": "大复现小，小复现大；",
   "pinyin": "dà fù xiàn xiǎo xiǎo fù xiàn dà",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 687,
   "text": "净复现秽，秽复现净；",
   "pinyin": "jìng fù xiàn huì huì fù xiàn jìng",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 688,
   "text": "佛身不可思议，众生身不可思议，乃至世界不可思议。",
   "pinyin": "fó shēn bù kě sī yì zhòng shēng shēn bù kě sī yì nǎi zhì shì jiè bù kě sī yì",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 689,
   "text": "当佛现此神变之时，十千女人现转女身得神通三昧，",
   "pinyin": "dāng fó xiàn cǐ shén biàn zhī shí shí qiān nǚ rén xiàn zhuǎn nǚ shēn dé shén tōng sān mèi",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 690,
   "text": "无量天人得无生法忍，无量阿修罗等成菩萨道，恒河沙菩萨现身成佛。",
   "pinyin": "wú liàng tiān rén dé wú shēng fǎ rěn wú liàng ā xiū luó děng chéng pú sà dào héng hé shā pú sà xiàn shēn chéng fó",
   "part": "长行",
   "heading": "不思议品第六"
  },
  {
   "n": 691,
   "text": "尔时，波斯匿王睹佛神变——见千花台上遍照如来，千华叶上千化身佛，",
   "pinyin": "ěr shí bō sī nì wáng dǔ fó shén biàn jiàn qiān huā tái shàng biàn zhào rú lái qiān huá yè shàng qiān huà shēn fó",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 692,
   "text": "千花叶中无量诸佛，各说般若波罗蜜多——白佛言：",
   "pinyin": "qiān huā yè zhōng wú liàng zhū fó gè shuō bō rě bō luó mì duō bái fó yán",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 693,
   "text": "世尊！",
   "pinyin": "shì zūn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 694,
   "text": "如是无量般若波罗蜜多，不可识识、不可智知。",
   "pinyin": "rú shì wú liàng bō rě bō luó mì duō bù kě shí shí bù kě zhì zhī",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 695,
   "text": "云何诸善男子于此经中，明了觉解、为人演说？",
   "pinyin": "yún hé zhū shàn nán zǐ yú cǐ jīng zhōng míng liǎo jué jiě wèi rén yǎn shuō",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 696,
   "text": "佛言：",
   "pinyin": "fó yán",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 697,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 698,
   "text": "汝今谛听！",
   "pinyin": "rǔ jīn dì tīng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 699,
   "text": "从初习忍至金刚定，如法修行十三观门，皆为法师依持建立。",
   "pinyin": "cóng chū xí rěn zhì jīn gāng dìng rú fǎ xiū xíng shí sān guān mén jiē wéi fǎ shī yī chí jiàn lì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 700,
   "text": "汝等大众，应当如佛而供养之，百千万亿天妙香花而以奉上。",
   "pinyin": "rǔ děng dà zhòng yīng dāng rú fó ér gòng yǎng zhī bǎi qiān wàn yì tiān miào xiāng huā ér yǐ fèng shàng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 701,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 702,
   "text": "其法师者习种性菩萨，若比丘、比丘尼、优婆塞、优婆夷修十住行，",
   "pinyin": "qí fǎ shī zhě xí zhǒng xìng pú sà ruò bǐ qiū bǐ qiū ní yōu pó sāi yōu pó yí xiū shí zhù xíng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 703,
   "text": "见佛、法、僧发菩提心，于诸众生利乐悲愍，自观己身六界诸根，",
   "pinyin": "jiàn fó fǎ sēng fā pú tí xīn yú zhū zhòng shēng lì lè bēi mǐn zì guān jǐ shēn liù jiè zhū gēn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 704,
   "text": "一切无常、苦、空、无我，了知业行生死涅槃，",
   "pinyin": "yí qiè wú cháng kǔ kōng wú wǒ liǎo zhī yè xíng shēng sǐ niè pán",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 705,
   "text": "能利自他饶益安乐——闻赞佛毁佛心定不动，闻有佛无佛心定不退；",
   "pinyin": "néng lì zì tā ráo yì ān lè wén zàn fó huǐ fó xīn dìng bù dòng wén yǒu fó wú fó xīn dìng bù tuì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 706,
   "text": "三业无失，起六和敬，方便善巧调伏众生，",
   "pinyin": "sān yè wú shī qǐ liù hé jìng fāng biàn shàn qiǎo tiáo fú zhòng shēng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 707,
   "text": "勤学十智神通化利，下品修习八万四千波罗蜜多。",
   "pinyin": "qín xué shí zhì shén tōng huà lì xià pǐn xiū xí bā wàn sì qiān bō luó mì duō",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 708,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 709,
   "text": "习忍以前经十千劫，行十善行有退有进，譬如轻毛随风东西。",
   "pinyin": "xí rěn yǐ qián jīng shí qiān jié xíng shí shàn xíng yǒu tuì yǒu jìn pì rú qīng máo suí fēng dōng xī",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 710,
   "text": "若至忍位，入正定聚，不作五逆、不谤正法，知我法相悉皆空故，住解脱位。",
   "pinyin": "ruò zhì rěn wèi rù zhèng dìng jù bù zuò wǔ nì bù bàng zhèng fǎ zhī wǒ fǎ xiàng xī jiē kōng gù zhù jiě tuō wèi",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 711,
   "text": "于一阿僧祇劫修习此忍，能起胜行。",
   "pinyin": "yú yī ā sēng qí jié xiū xí cǐ rěn néng qǐ shèng xíng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 712,
   "text": "复次，性种性菩萨，住无分别，修十慧观，舍财命故，持净戒故，心谦下故，",
   "pinyin": "fù cì xìng zhǒng xìng pú sà zhù wú fēn bié xiū shí huì guān shě cái mìng gù chí jìng jiè gù xīn qiān xià gù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 713,
   "text": "利自他故，生死无乱故，无相甚深故，达有如幻故，不求果报故，得无碍解故，",
   "pinyin": "lì zì tā gù shēng sǐ wú luàn gù wú xiàng shèn shēn gù dá yǒu rú huàn gù bù qiú guǒ bào gù dé wú ài jiě gù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 714,
   "text": "念念示现佛神力故，对治四倒、三不善根、三世惑业、十颠倒故，",
   "pinyin": "niàn niàn shì xiàn fó shén lì gù duì zhì sì dǎo sān bù shàn gēn sān shì huò yè shí diān dǎo gù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 715,
   "text": "我人知见念念虚伪，了达名假、受假、法假皆不可得，无自他相，住真实观。",
   "pinyin": "wǒ rén zhī jiàn niàn niàn xū wěi liǎo dá míng jiǎ shòu jiǎ fǎ jiǎ jiē bù kě dé wú zì tā xiàng zhù zhēn shí guān",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 716,
   "text": "中品修习八万四千波罗蜜多，于二阿僧祇劫行诸胜行，得坚忍位。",
   "pinyin": "zhōng pǐn xiū xí bā wàn sì qiān bō luó mì duō yú èr ā sēng qí jié xíng zhū shèng xíng dé jiān rěn wèi",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 717,
   "text": "复次，道种性菩萨，住坚忍中观诸法性，得无生灭，",
   "pinyin": "fù cì dào zhǒng xìng pú sà zhù jiān rěn zhōng guān zhū fǎ xìng dé wú shēng miè",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 718,
   "text": "四无量心能破诸暗，常见诸佛广兴供养，常学诸佛住回向心，",
   "pinyin": "sì wú liàng xīn néng pò zhū àn cháng jiàn zhū fó guǎng xīng gòng yǎng cháng xué zhū fó zhù huí xiàng xīn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 719,
   "text": "所修善根皆如实际，能于三昧广作佛事，现种种身行四摄法，",
   "pinyin": "suǒ xiū shàn gēn jiē rú shí jì néng yú sān mèi guǎng zuò fó shì xiàn zhǒng zhǒng shēn xíng sì shè fǎ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 720,
   "text": "住无分别化利众生，智慧明了甚深观察，一切行愿普皆修习，",
   "pinyin": "zhù wú fēn bié huà lì zhòng shēng zhì huì míng liǎo shèn shēn guān chá yí qiè xíng yuàn pǔ jiē xiū xí",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 721,
   "text": "能为法师调御有情，善观五蕴三界二谛，无自他相得如实性。",
   "pinyin": "néng wéi fǎ shī tiáo yù yǒu qíng shàn guān wǔ yùn sān jiè èr dì wú zì tā xiàng dé rú shí xìng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 722,
   "text": "虽常修胜义而受生三界。",
   "pinyin": "suī cháng xiū shèng yì ér shòu shēng sān jiè",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 723,
   "text": "何以故？",
   "pinyin": "hé yǐ gù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 724,
   "text": "业习果报未坏尽故，于人天中顺道生故。",
   "pinyin": "yè xí guǒ bào wèi huài jìn gù yú rén tiān zhōng shùn dào shēng gù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 725,
   "text": "上品修习八万四千波罗蜜多，三阿僧祇劫修二利行，广大饶益，",
   "pinyin": "shàng pǐn xiū xí bā wàn sì qiān bō luó mì duō sān ā sēng qí jié xiū èr lì xíng guǎng dà ráo yì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 726,
   "text": "得善调伏诸三摩地，住胜观察，修出离行，能证平等圣人地故。",
   "pinyin": "dé shàn tiáo fú zhū sān mó dì zhù shèng guān chá xiū chū lí xíng néng zhèng píng děng shèng rén dì gù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 727,
   "text": "复次欢喜地菩萨摩诃萨，超愚夫地，生如来家，住平等忍。",
   "pinyin": "fù cì huān xǐ dì pú sà mó hē sà chāo yú fū dì shēng rú lái jiā zhù píng děng rěn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 728,
   "text": "初无相智照胜义谛，一相平等非相无相，断诸无明灭三界贪，",
   "pinyin": "chū wú xiàng zhì zhào shèng yì dì yī xiàng píng děng fēi xiàng wú xiàng duàn zhū wú míng miè sān jiè tān",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 729,
   "text": "未来无量生死永不生故，大悲为首起诸大愿，",
   "pinyin": "wèi lái wú liàng shēng sǐ yǒng bù shēng gù dà bēi wéi shǒu qǐ zhū dà yuàn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 730,
   "text": "于方便智念念修习无量胜行——非证非不证，一切遍学故；",
   "pinyin": "yú fāng biàn zhì niàn niàn xiū xí wú liàng shèng xíng fēi zhèng fēi bù zhèng yí qiè biàn xué gù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 731,
   "text": "非住非不住，向一切智故；",
   "pinyin": "fēi zhù fēi bù zhù xiàng yí qiè zhì gù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 732,
   "text": "行于生死，魔不动故；",
   "pinyin": "xíng yú shēng sǐ mó bù dòng gù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 733,
   "text": "离我我所，无怖畏故；",
   "pinyin": "lí wǒ wǒ suǒ wú bù wèi gù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 734,
   "text": "无自他相，常化众生故；",
   "pinyin": "wú zì tā xiàng cháng huà zhòng shēng gù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 735,
   "text": "自在愿力，生诸净土故。",
   "pinyin": "zì zài yuàn lì shēng zhū jìng tǔ gù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 736,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 737,
   "text": "此初觉智，非如非智，非有非无，无有二相方便妙用，非倒非住，",
   "pinyin": "cǐ chū jué zhì fēi rú fēi zhì fēi yǒu fēi wú wú yǒu èr xiàng fāng biàn miào yòng fēi dǎo fēi zhù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 738,
   "text": "非动非静，二利自在，如水与波非一非异，智起诸波罗蜜多，亦非一异。",
   "pinyin": "fēi dòng fēi jìng èr lì zì zài rú shuǐ yǔ bō fēi yī fēi yì zhì qǐ zhū bō luó mì duō yì fēi yī yì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 739,
   "text": "于四阿僧祇劫，满足修习百万行愿，此地菩萨无三界业习，更不造新。",
   "pinyin": "yú sì ā sēng qí jié mǎn zú xiū xí bǎi wàn xíng yuàn cǐ dì pú sà wú sān jiè yè xí gèng bù zào xīn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 740,
   "text": "由随智力，以愿生故。",
   "pinyin": "yóu suí zhì lì yǐ yuàn shēng gù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 741,
   "text": "念念常行檀波罗蜜多，布施、爱语、利行、同事，广大清净，善能安住饶益众生。",
   "pinyin": "niàn niàn cháng xíng tán bō luó mì duō bù shī ài yǔ lì xíng tóng shì guǎng dà qīng jìng shàn néng ān zhù ráo yì zhòng shēng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 742,
   "text": "复次，离垢地菩萨摩诃萨，四无量心最胜寂灭，断瞋等习修一切行，",
   "pinyin": "fù cì lí gòu dì pú sà mó hē sà sì wú liàng xīn zuì shèng jì miè duàn chēn děng xí xiū yí qiè xíng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 743,
   "text": "所谓远离杀害、不与不取，心无染欲，得真实语、得和合语、得柔软语、得调伏语，",
   "pinyin": "suǒ wèi yuǎn lí shā hài bù yǔ bù qǔ xīn wú rǎn yù dé zhēn shí yǔ dé hé hé yǔ dé róu ruǎn yǔ dé tiáo fú yǔ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 744,
   "text": "常行舍心、常起慈心、住正直心，寂静纯善，离破戒垢，行大慈观念念现前。",
   "pinyin": "cháng xíng shě xīn cháng qǐ cí xīn zhù zhèng zhí xīn jì jìng chún shàn lí pò jiè gòu xíng dà cí guān niàn niàn xiàn qián",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 745,
   "text": "于五阿僧祇劫，具足清净戒波罗蜜多，志意勇猛永离诸染。",
   "pinyin": "yú wǔ ā sēng qí jié jù zú qīng jìng jiè bō luó mì duō zhì yì yǒng měng yǒng lí zhū rǎn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 746,
   "text": "复次，发光地菩萨摩诃萨，住无分别，灭无明暗，",
   "pinyin": "fù cì fā guāng dì pú sà mó hē sà zhù wú fēn bié miè wú míng àn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 747,
   "text": "于无相忍而得三明，悉知三世无来无去；",
   "pinyin": "yú wú xiàng rěn ér dé sān míng xī zhī sān shì wú lái wú qù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 748,
   "text": "依四静虑、四无色定，无分别智次第随顺，具足胜定，",
   "pinyin": "yī sì jìng lǜ sì wú sè dìng wú fēn bié zhì cì dì suí shùn jù zú shèng dìng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 749,
   "text": "得五神通——现身大小隐显自在，天眼清净悉见诸趣，",
   "pinyin": "dé wǔ shén tōng xiàn shēn dà xiǎo yǐn xiǎn zì zài tiān yǎn qīng jìng xī jiàn zhū qù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 750,
   "text": "天耳清净悉闻众声，以他心智知众生心，宿住能知无量差别。",
   "pinyin": "tiān ěr qīng jìng xī wén zhòng shēng yǐ tā xīn zhì zhī zhòng shēng xīn sù zhù néng zhī wú liàng chā bié",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 751,
   "text": "于六阿僧祇劫，行一切忍波罗蜜多，得大总持利益安乐。",
   "pinyin": "yú liù ā sēng qí jié xíng yí qiè rěn bō luó mì duō dé dà zǒng chí lì yì ān lè",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 752,
   "text": "复次，焰慧地菩萨摩诃萨，修行顺忍，无所摄受，永断微细身边见故，",
   "pinyin": "fù cì yàn huì dì pú sà mó hē sà xiū xíng shùn rěn wú suǒ shè shòu yǒng duàn wēi xì shēn biān jiàn gù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 753,
   "text": "修习无边菩提分法——念处、正勤、神足、根、力、觉道具足，",
   "pinyin": "xiū xí wú biān pú tí fēn fǎ niàn chù zhèng qín shén zú gēn lì jué dào jù zú",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 754,
   "text": "为欲成就力、无所畏、不共佛法。",
   "pinyin": "wèi yù chéng jiù lì wú suǒ wèi bù gòng fó fǎ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 755,
   "text": "于七阿僧祇劫，修习无量精进波罗蜜多，远离懈怠，普利众生。",
   "pinyin": "yú qī ā sēng qí jié xiū xí wú liàng jīng jìn bō luó mì duō yuǎn lí xiè dài pǔ lì zhòng shēng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 756,
   "text": "复次，难胜地菩萨摩诃萨，以四无畏随顺真如，清净平等无差别相，",
   "pinyin": "fù cì nán shèng dì pú sà mó hē sà yǐ sì wú wèi suí shùn zhēn rú qīng jìng píng děng wú chā bié xiàng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 757,
   "text": "断随小乘乐求涅槃，集诸功德具观诸谛——此苦圣谛，集、灭、道谛；",
   "pinyin": "duàn suí xiǎo shèng yào qiú niè pán jí zhū gōng dé jù guān zhū dì cǐ kǔ shèng dì jí miè dào dì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 758,
   "text": "世俗、胜义，观无量谛。",
   "pinyin": "shì sú shèng yì guān wú liàng dì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 759,
   "text": "为利众生，习诸技艺——文字、医方、赞咏、戏笑、工巧、呪术、外道异论，",
   "pinyin": "wèi lì zhòng shēng xí zhū jì yì wén zì yī fāng zàn yǒng xì xiào gōng qiǎo zhòu shù wài dào yì lùn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 760,
   "text": "吉凶占相一无错谬，但于众生不为损恼，为利益故咸悉开示，",
   "pinyin": "jí xiōng zhàn xiàng yī wú cuò miù dàn yú zhòng shēng bù wéi sǔn nǎo wèi lì yì gù xián xī kāi shì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 761,
   "text": "渐令安住无上菩提，知诸地中出道障道。",
   "pinyin": "jiàn lìng ān zhù wú shàng pú tí zhī zhū dì zhōng chū dào zhàng dào",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 762,
   "text": "于八阿僧祇劫，常修三昧，开发诸行。",
   "pinyin": "yú bā ā sēng qí jié cháng xiū sān mèi kāi fā zhū xíng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 763,
   "text": "复次，现前地菩萨摩诃萨，得上顺忍，住三脱门。",
   "pinyin": "fù cì xiàn qián dì pú sà mó hē sà dé shàng shùn rěn zhù sān tuō mén",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 764,
   "text": "能尽三界集因集业，粗现行相。",
   "pinyin": "néng jìn sān jiè jí yīn jí yè cū xiàn xíng xiàng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 765,
   "text": "大悲增上，观诸生死：",
   "pinyin": "dà bēi zēng shàng guān zhū shēng sǐ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 766,
   "text": "无明暗覆，业集，识种，名色、六处、触、受、爱、取、有、生、老死等皆由著我。",
   "pinyin": "wú míng àn fù yè jí shí zhǒng míng sè liù chù chù shòu ài qǔ yǒu shēng lǎo sǐ děng jiē yóu zhuó wǒ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 767,
   "text": "无明业果，非有非无，一相无相而不二故。",
   "pinyin": "wú míng yè guǒ fēi yǒu fēi wú yī xiàng wú xiàng ér bù èr gù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 768,
   "text": "于九阿僧祇劫，行百万空、无相、无愿三昧，得一切般若波罗蜜多无边光照。",
   "pinyin": "yú jiǔ ā sēng qí jié xíng bǎi wàn kōng wú xiàng wú yuàn sān mèi dé yí qiè bō rě bō luó mì duō wú biān guāng zhào",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 769,
   "text": "复次，远行地菩萨摩诃萨，修无生忍，证法无别，断诸业果细现行相，",
   "pinyin": "fù cì yuǎn xíng dì pú sà mó hē sà xiū wú shēng rěn zhèng fǎ wú bié duàn zhū yè guǒ xì xiàn xíng xiàng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 770,
   "text": "住于灭定，起殊胜行，虽常寂灭，广化众生——示入声闻，常随佛智；",
   "pinyin": "zhù yú miè dìng qǐ shū shèng xíng suī cháng jì miè guǎng huà zhòng shēng shì rù shēng wén cháng suí fó zhì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 771,
   "text": "示同外道，示作魔王，随顺世间而常出世。",
   "pinyin": "shì tóng wài dào shì zuò mó wáng suí shùn shì jiān ér cháng chū shì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 772,
   "text": "于十阿僧祇劫，行百万三昧，善巧方便广宣法藏，一切庄严皆得圆满。",
   "pinyin": "yú shí ā sēng qí jié xíng bǎi wàn sān mèi shàn qiǎo fāng biàn guǎng xuān fǎ zàng yí qiè zhuāng yán jiē dé yuán mǎn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 773,
   "text": "复次，不动地菩萨摩诃萨，住无生忍，体无增减，",
   "pinyin": "fù cì bù dòng dì pú sà mó hē sà zhù wú shēng rěn tǐ wú zēng jiǎn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 774,
   "text": "断诸功用，心心寂灭，无身心相犹如虚空。",
   "pinyin": "duàn zhū gōng yòng xīn xīn jì miè wú shēn xīn xiàng yóu rú xū kōng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 775,
   "text": "此菩萨，佛心、菩提心、涅槃心，悉皆不起，",
   "pinyin": "cǐ pú sà fó xīn pú tí xīn niè pán xīn xī jiē bù qǐ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 776,
   "text": "由本愿故诸佛加持，能一念顷而起智业双照平等，",
   "pinyin": "yóu běn yuàn gù zhū fó jiā chí néng yī niàn qǐng ér qǐ zhì yè shuāng zhào píng děng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 777,
   "text": "以十力智遍不可说大千世界，随诸众生普皆利乐。",
   "pinyin": "yǐ shí lì zhì biàn bù kě shuō dà qiān shì jiè suí zhū zhòng shēng pǔ jiē lì lè",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 778,
   "text": "于千阿僧祇劫，满足百万大愿，心心趣入一切种、一切智智。",
   "pinyin": "yú qiān ā sēng qí jié mǎn zú bǎi wàn dà yuàn xīn xīn qù rù yí qiè zhǒng yí qiè zhì zhì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 779,
   "text": "复次，善慧地菩萨摩诃萨，住上无生忍，灭心心相，证智自在，",
   "pinyin": "fù cì shàn huì dì pú sà mó hē sà zhù shàng wú shēng rěn miè xīn xīn xiàng zhèng zhì zì zài",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 780,
   "text": "断无碍障，具大神通，修力无畏，善能守护诸佛法藏，",
   "pinyin": "duàn wú ài zhàng jù dà shén tōng xiū lì wú wèi shàn néng shǒu hù zhū fó fǎ zàng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 781,
   "text": "得无碍解——法、义、词、辩，演说正法无断无尽。",
   "pinyin": "dé wú ài jiě fǎ yì cí biàn yǎn shuō zhèng fǎ wú duàn wú jìn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 782,
   "text": "一刹那顷于不可说诸世界中，随诸众生所有问难，一音解释普令欢喜。",
   "pinyin": "yī chà nà qǐng yú bù kě shuō zhū shì jiè zhōng suí zhū zhòng shēng suǒ yǒu wèn nàn yī yīn jiě shì pǔ lìng huān xǐ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 783,
   "text": "于万阿僧祇劫，能现百万恒河沙等诸佛神力，无尽法藏利益圆满。",
   "pinyin": "yú wàn ā sēng qí jié néng xiàn bǎi wàn héng hé shā děng zhū fó shén lì wú jìn fǎ zàng lì yì yuán mǎn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 784,
   "text": "复次，法云地菩萨摩诃萨，无量智慧思惟观察，从发信心，",
   "pinyin": "fù cì fǎ yún dì pú sà mó hē sà wú liàng zhì huì sī wéi guān chá cóng fā xìn xīn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 785,
   "text": "经百万阿僧祇劫，广集无量助道法，增长无边大福智，证业自在，",
   "pinyin": "jīng bǎi wàn ā sēng qí jié guǎng jí wú liàng zhù dào fǎ zēng zhǎng wú biān dà fú zhì zhèng yè zì zài",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 786,
   "text": "断神通障，于一念顷能遍十方百万亿阿僧祇世界微尘数国土，",
   "pinyin": "duàn shén tōng zhàng yú yī niàn qǐng néng biàn shí fāng bǎi wàn yì ā sēng qí shì jiè wēi chén shù guó tǔ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 787,
   "text": "悉知一切众生心行上中下根，为说三乘，普令修习波罗蜜多。",
   "pinyin": "xī zhī yí qiè zhòng shēng xīn xíng shàng zhōng xià gēn wèi shuō sān shèng pǔ lìng xiū xí bō luó mì duō",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 788,
   "text": "入佛行处、力、无所畏，随顺如来寂灭转依。",
   "pinyin": "rù fó xíng chù lì wú suǒ wèi suí shùn rú lái jì miè zhuǎn yī",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 789,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 790,
   "text": "从初习忍至金刚定，皆名为伏一切烦恼。",
   "pinyin": "cóng chū xí rěn zhì jīn gāng dìng jiē míng wéi fú yí qiè fán nǎo",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 791,
   "text": "无相信忍，照胜义谛，灭诸烦恼，生解脱智。",
   "pinyin": "wú xiàng xìn rěn zhào shèng yì dì miè zhū fán nǎo shēng jiě tuō zhì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 792,
   "text": "渐渐伏灭，以生灭心得无生灭。",
   "pinyin": "jiàn jiàn fú miè yǐ shēng miè xīn dé wú shēng miè",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 793,
   "text": "此心若灭即无明灭。",
   "pinyin": "cǐ xīn ruò miè jí wú míng miè",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 794,
   "text": "金刚定前所有知见，皆不名见。",
   "pinyin": "jīn gāng dìng qián suǒ yǒu zhī jiàn jiē bù míng jiàn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 795,
   "text": "唯佛顿解，具一切智，所有知见而得名见。",
   "pinyin": "wéi fó dùn jiě jù yí qiè zhì suǒ yǒu zhī jiàn ér dé míng jiàn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 796,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 797,
   "text": "金刚三昧现在前时，而亦未能等无等等，",
   "pinyin": "jīn gāng sān mèi xiàn zài qián shí ér yì wèi néng děng wú děng děng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 798,
   "text": "譬如有人登大高台，普观一切无不斯了。",
   "pinyin": "pì rú yǒu rén dēng dà gāo tái pǔ guān yí qiè wú bù sī liǎo",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 799,
   "text": "若解脱位，一相无相，无生无灭，同真际、等法性，满功德藏，住如来位。",
   "pinyin": "ruò jiě tuō wèi yī xiàng wú xiàng wú shēng wú miè tóng zhēn jì děng fǎ xìng mǎn gōng dé zàng zhù rú lái wèi",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 800,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 801,
   "text": "如是诸菩萨摩诃萨，受持，解说，皆往十方诸佛刹土，利安有情，通达实相；",
   "pinyin": "rú shì zhū pú sà mó hē sà shòu chí jiě shuō jiē wǎng shí fāng zhū fó chà tǔ lì ān yǒu qíng tōng dá shí xiàng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 802,
   "text": "如我今日等无有异。",
   "pinyin": "rú wǒ jīn rì děng wú yǒu yì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 803,
   "text": "善男子！",
   "pinyin": "shàn nán zǐ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 804,
   "text": "十方法界一切如来，皆依此门而得成佛；",
   "pinyin": "shí fāng fǎ jiè yí qiè rú lái jiē yī cǐ mén ér dé chéng fó",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 805,
   "text": "若言越此得成佛者，是魔所说，非是佛说。",
   "pinyin": "ruò yán yuè cǐ dé chéng fó zhě shì mó suǒ shuō fēi shì fó shuō",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 806,
   "text": "是故汝等应如是知，如是见，如是信解。",
   "pinyin": "shì gù rǔ děng yīng rú shì zhī rú shì jiàn rú shì xìn jiě",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 807,
   "text": "尔时，世尊欲重宣此义，而说偈言：",
   "pinyin": "ěr shí shì zūn yù chóng xuān cǐ yì ér shuō jì yán",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 808,
   "text": "彼伏忍菩萨，",
   "pinyin": "bǐ fú rěn pú sà",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 809,
   "text": "于佛法长养，",
   "pinyin": "yú fó fǎ zhǎng yǎng",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 810,
   "text": "坚固三十心，",
   "pinyin": "jiān gù sān shí xīn",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 811,
   "text": "名为不退转。",
   "pinyin": "míng wéi bù tuì zhuǎn",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 812,
   "text": "初证平等性，",
   "pinyin": "chū zhèng píng děng xìng",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 813,
   "text": "而生诸佛家，",
   "pinyin": "ér shēng zhū fó jiā",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 814,
   "text": "由初得觉悟，",
   "pinyin": "yóu chū dé jué wù",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 815,
   "text": "名为欢喜地。",
   "pinyin": "míng wéi huān xǐ dì",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 816,
   "text": "远离于染污，",
   "pinyin": "yuǎn lí yú rǎn wū",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 817,
   "text": "瞋等种种垢，",
   "pinyin": "chēn děng zhǒng zhǒng gòu",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 818,
   "text": "具戒德清净，",
   "pinyin": "jù jiè dé qīng jìng",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 819,
   "text": "名为离垢地。",
   "pinyin": "míng wéi lí gòu dì",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 820,
   "text": "灭坏无明暗，",
   "pinyin": "miè huài wú míng àn",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 821,
   "text": "而得诸禅定，",
   "pinyin": "ér dé zhū chán dìng",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 822,
   "text": "照曜由慧光，",
   "pinyin": "zhào yào yóu huì guāng",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 823,
   "text": "名为发光地。",
   "pinyin": "míng wéi fā guāng dì",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 824,
   "text": "清净菩提分，",
   "pinyin": "qīng jìng pú tí fēn",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 825,
   "text": "远离身边见，",
   "pinyin": "yuǎn lí shēn biān jiàn",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 826,
   "text": "智慧焰炽然，",
   "pinyin": "zhì huì yàn chì rán",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 827,
   "text": "名为焰慧地。",
   "pinyin": "míng wéi yàn huì dì",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 828,
   "text": "如实知诸谛，",
   "pinyin": "rú shí zhī zhū dì",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 829,
   "text": "世间诸伎艺，",
   "pinyin": "shì jiān zhū jì yì",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 830,
   "text": "种种利群生，",
   "pinyin": "zhǒng zhǒng lì qún shēng",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 831,
   "text": "名为难胜地。",
   "pinyin": "míng wéi nán shèng dì",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 832,
   "text": "观察缘生法，",
   "pinyin": "guān chá yuán shēng fǎ",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 833,
   "text": "无明至老死，",
   "pinyin": "wú míng zhì lǎo sǐ",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 834,
   "text": "能证彼甚深，",
   "pinyin": "néng zhèng bǐ shèn shēn",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 835,
   "text": "名为现前地。",
   "pinyin": "míng wéi xiàn qián dì",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 836,
   "text": "方便三摩地，",
   "pinyin": "fāng biàn sān mó dì",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 837,
   "text": "示现无量身，",
   "pinyin": "shì xiàn wú liàng shēn",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 838,
   "text": "善巧应群生，",
   "pinyin": "shàn qiǎo yìng qún shēng",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 839,
   "text": "名为远行地。",
   "pinyin": "míng wéi yuǎn xíng dì",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 840,
   "text": "住于无相海，",
   "pinyin": "zhù yú wú xiàng hǎi",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 841,
   "text": "一切佛加持，",
   "pinyin": "yí qiè fó jiā chí",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 842,
   "text": "自在破魔军，",
   "pinyin": "zì zài pò mó jūn",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 843,
   "text": "名为不动地。",
   "pinyin": "míng wéi bù dòng dì",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 844,
   "text": "得四无碍解，",
   "pinyin": "dé sì wú ài jiě",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 845,
   "text": "一音演一切，",
   "pinyin": "yī yīn yǎn yí qiè",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 846,
   "text": "闻者悉欢喜，",
   "pinyin": "wén zhě xī huān xǐ",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 847,
   "text": "名为善慧地。",
   "pinyin": "míng wéi shàn huì dì",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 848,
   "text": "智慧如密云，",
   "pinyin": "zhì huì rú mì yún",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 849,
   "text": "遍满于法界，",
   "pinyin": "biàn mǎn yú fǎ jiè",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 850,
   "text": "普洒甘露法，",
   "pinyin": "pǔ sǎ gān lù fǎ",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 851,
   "text": "名为法云地。",
   "pinyin": "míng wéi fǎ yún dì",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 852,
   "text": "满足无漏界，",
   "pinyin": "mǎn zú wú lòu jiè",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 853,
   "text": "常净解脱身，",
   "pinyin": "cháng jìng jiě tuō shēn",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 854,
   "text": "寂灭不思议，",
   "pinyin": "jì miè bù sī yì",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 855,
   "text": "名为一切智。",
   "pinyin": "míng wéi yí qiè zhì",
   "part": "偈颂",
   "heading": "奉持品第七"
  },
  {
   "n": 856,
   "text": "佛告波斯匿王：",
   "pinyin": "fó gào bō sī nì wáng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 857,
   "text": "我灭度后，法欲灭时，一切有情造恶业故，令诸国土种种灾起。",
   "pinyin": "wǒ miè dù hòu fǎ yù miè shí yí qiè yǒu qíng zào è yè gù lìng zhū guó tǔ zhǒng zhǒng zāi qǐ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 858,
   "text": "诸国王等，为护自身、太子、王子、后妃、眷属、百官、百姓、一切国土，",
   "pinyin": "zhū guó wáng děng wèi hù zì shēn tài zǐ wáng zǐ hòu fēi juàn shǔ bǎi guān bǎi xìng yí qiè guó tǔ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 859,
   "text": "即当受持此般若波罗蜜多，皆得安乐。",
   "pinyin": "jí dāng shòu chí cǐ bō rě bō luó mì duō jiē dé ān lè",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 860,
   "text": "我以是经付嘱国王，不付比丘、比丘尼、优婆塞、优婆夷。",
   "pinyin": "wǒ yǐ shì jīng fù zhǔ guó wáng bù fù bǐ qiū bǐ qiū ní yōu pó sāi yōu pó yí",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 861,
   "text": "所以者何？",
   "pinyin": "suǒ yǐ zhě hé",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 862,
   "text": "无王威力，不能建立，是故汝等常当受持、读诵、解说。",
   "pinyin": "wú wáng wēi lì bù néng jiàn lì shì gù rǔ děng cháng dāng shòu chí dú sòng jiě shuō",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 863,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 864,
   "text": "吾今所化大千世界，百亿须弥，百亿日月，一一须弥有四天下。",
   "pinyin": "wú jīn suǒ huà dà qiān shì jiè bǎi yì xū mí bǎi yì rì yuè yī yī xū mí yǒu sì tiān xià",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 865,
   "text": "此赡部洲，十六大国、五百中国、十万小国，是诸国中若七难起，",
   "pinyin": "cǐ shàn bù zhōu shí liù dà guó wǔ bǎi zhōng guó shí wàn xiǎo guó shì zhū guó zhōng ruò qī nàn qǐ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 866,
   "text": "一切国王为除难故，受持、解说此般若波罗蜜多，七难即灭，国土安乐。",
   "pinyin": "yí qiè guó wáng wèi chú nàn gù shòu chí jiě shuō cǐ bō rě bō luó mì duō qī nàn jí miè guó tǔ ān lè",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 867,
   "text": "波斯匿王言：",
   "pinyin": "bō sī nì wáng yán",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 868,
   "text": "云何七难？",
   "pinyin": "yún hé qī nàn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 869,
   "text": "佛言：",
   "pinyin": "fó yán",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 870,
   "text": "一者，日月失度。",
   "pinyin": "yī zhě rì yuè shī dù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 871,
   "text": "日色改变——白色、赤色、黄色、黑色，或二三四五日并照；",
   "pinyin": "rì sè gǎi biàn bái sè chì sè huáng sè hēi sè huò èr sān sì wǔ rì bìng zhào",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 872,
   "text": "月色改变——赤色、黄色；",
   "pinyin": "yuè sè gǎi biàn chì sè huáng sè",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 873,
   "text": "日月薄蚀，或有重轮——一二三四五重轮现。",
   "pinyin": "rì yuè bó shí huò yǒu chóng lún yī èr sān sì wǔ chóng lún xiàn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 874,
   "text": "二者，星辰失度。",
   "pinyin": "èr zhě xīng chén shī dù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 875,
   "text": "彗星、木星、火星、金星、水星、土等诸星，各各为变，或时昼出。",
   "pinyin": "huì xīng mù xīng huǒ xīng jīn xīng shuǐ xīng tǔ děng zhū xīng gè gè wéi biàn huò shí zhòu chū",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 876,
   "text": "三者，龙火、鬼火、人火、树火，大火四起焚烧万物。",
   "pinyin": "sān zhě lóng huǒ guǐ huǒ rén huǒ shù huǒ dà huǒ sì qǐ fén shāo wàn wù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 877,
   "text": "四者，时节改变，寒暑不恒。",
   "pinyin": "sì zhě shí jié gǎi biàn hán shǔ bù héng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 878,
   "text": "冬雨雷电，夏霜冰雪，雨土石山及以砂砾，",
   "pinyin": "dōng yǔ léi diàn xià shuāng bīng xuě yǔ tǔ shí shān jí yǐ shā lì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 879,
   "text": "非时降雹，雨赤黑水，江河泛涨，流石浮山。",
   "pinyin": "fēi shí jiàng báo yǔ chì hēi shuǐ jiāng hé fàn zhǎng liú shí fú shān",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 880,
   "text": "五者，暴风数起，昏蔽日月，发屋拔树，飞沙走石。",
   "pinyin": "wǔ zhě bào fēng shuò qǐ hūn bì rì yuè fā wū bá shù fēi shā zǒu shí",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 881,
   "text": "六者，天地亢阳，陂池竭涸，草木枯死，百谷不成。",
   "pinyin": "liù zhě tiān dì kàng yáng bēi chí jié hé cǎo mù kū sǐ bǎi gǔ bù chéng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 882,
   "text": "七者，四方贼来侵国内外，兵戈竞起百姓丧亡。",
   "pinyin": "qī zhě sì fāng zéi lái qīn guó nèi wài bīng gē jìng qǐ bǎi xìng sàng wáng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 883,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 884,
   "text": "我今略说如是诸难。",
   "pinyin": "wǒ jīn lüè shuō rú shì zhū nàn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 885,
   "text": "其有日昼不现、月夜不现；",
   "pinyin": "qí yǒu rì zhòu bù xiàn yuè yè bù xiàn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 886,
   "text": "天种种灾，无云雨雪；",
   "pinyin": "tiān zhǒng zhǒng zāi wú yún yǔ xuě",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 887,
   "text": "地种种灾，崩裂震动，或复血流；",
   "pinyin": "dì zhǒng zhǒng zāi bēng liè zhèn dòng huò fù xuè liú",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 888,
   "text": "鬼神出现，鸟兽怪异。",
   "pinyin": "guǐ shén chū xiàn niǎo shòu guài yì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 889,
   "text": "如是灾难无量无边，一一灾起，皆须受持、读诵、解说此般若波罗蜜多。",
   "pinyin": "rú shì zāi nàn wú liàng wú biān yī yī zāi qǐ jiē xū shòu chí dú sòng jiě shuō cǐ bō rě bō luó mì duō",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 890,
   "text": "尔时，十六国王闻佛所说，皆悉惊怖。",
   "pinyin": "ěr shí shí liù guó wáng wén fó suǒ shuō jiē xī jīng bù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 891,
   "text": "波斯匿王白佛言：",
   "pinyin": "bō sī nì wáng bái fó yán",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 892,
   "text": "世尊！",
   "pinyin": "shì zūn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 893,
   "text": "何故天地有是灾难？",
   "pinyin": "hé gù tiān dì yǒu shì zāi nàn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 894,
   "text": "佛言：",
   "pinyin": "fó yán",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 895,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 896,
   "text": "由赡部洲大小国邑一切人民，不孝父母，不敬师长、沙门、婆罗门；",
   "pinyin": "yóu shàn bù zhōu dà xiǎo guó yì yí qiè rén mín bù xiào fù mǔ bù jìng shī zhǎng shā mén pó luó mén",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 897,
   "text": "国王、大臣不行正法，由此诸恶有是难兴。",
   "pinyin": "guó wáng dà chén bù xíng zhèng fǎ yóu cǐ zhū è yǒu shì nàn xīng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 898,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 899,
   "text": "般若波罗蜜多，",
   "pinyin": "bō rě bō luó mì duō",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 900,
   "text": "能出生一切诸佛法、一切菩萨解脱法、一切国王无上法、一切有情出离法，",
   "pinyin": "néng chū shēng yí qiè zhū fó fǎ yí qiè pú sà jiě tuō fǎ yí qiè guó wáng wú shàng fǎ yí qiè yǒu qíng chū lí fǎ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 901,
   "text": "如摩尼宝体具众德，能镇毒龙诸恶鬼神，能遂人心所求满足，",
   "pinyin": "rú mó ní bǎo tǐ jù zhòng dé néng zhèn dú lóng zhū è guǐ shén néng suì rén xīn suǒ qiú mǎn zú",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 902,
   "text": "能应轮王名如意珠，能令难陀、跋难陀等诸大龙王降霔甘雨润泽草木，",
   "pinyin": "néng yìng lún wáng míng rú yì zhū néng lìng nán tuó bá nán tuó děng zhū dà lóng wáng jiàng zhù gān yǔ rùn zé cǎo mù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 903,
   "text": "若于暗夜置高幢上，光照天地明如日出。",
   "pinyin": "ruò yú àn yè zhì gāo chuáng shàng guāng zhào tiān dì míng rú rì chū",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 904,
   "text": "此般若波罗蜜多亦复如是，汝等诸王应作宝幢及以幡盖，",
   "pinyin": "cǐ bō rě bō luó mì duō yì fù rú shì rǔ děng zhū wáng yīng zuò bǎo chuáng jí yǐ fān gài",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 905,
   "text": "烧香散花广大供养，宝函盛经置于宝案，若欲行时常导其前，",
   "pinyin": "shāo xiāng sàn huā guǎng dà gòng yǎng bǎo hán shèng jīng zhì yú bǎo àn ruò yù xíng shí cháng dǎo qí qián",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 906,
   "text": "所在住处作七宝帐，众宝为座置经于上，种种供养如事父母；",
   "pinyin": "suǒ zài zhù chù zuò qī bǎo zhàng zhòng bǎo wéi zuò zhì jīng yú shàng zhǒng zhǒng gòng yǎng rú shì fù mǔ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 907,
   "text": "亦如诸天奉事帝释。",
   "pinyin": "yì rú zhū tiān fèng shì dì shì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 908,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 909,
   "text": "我见诸国一切人王，皆由过去侍五百佛恭敬供养，得为帝王；",
   "pinyin": "wǒ jiàn zhū guó yí qiè rén wáng jiē yóu guò qù shì wǔ bǎi fó gōng jìng gòng yǎng dé wéi dì wáng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 910,
   "text": "一切圣人得道果者，来生其国，作大利益。",
   "pinyin": "yí qiè shèng rén dé dào guǒ zhě lái shēng qí guó zuò dà lì yì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 911,
   "text": "若王福尽、无道之时，圣人舍去，灾难竞起。",
   "pinyin": "ruò wáng fú jìn wú dào zhī shí shèng rén shě qù zāi nàn jìng qǐ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 912,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 913,
   "text": "若未来世，有诸国王建立正法、护三宝者，我令五方菩萨摩诃萨众往护其国。",
   "pinyin": "ruò wèi lái shì yǒu zhū guó wáng jiàn lì zhèng fǎ hù sān bǎo zhě wǒ lìng wǔ fāng pú sà mó hē sà zhòng wǎng hù qí guó",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 914,
   "text": "东方金刚手菩萨摩诃萨，手持金刚杵，放青色光，与四俱胝菩萨往护其国。",
   "pinyin": "dōng fāng jīn gāng shǒu pú sà mó hē sà shǒu chí jīn gāng chǔ fàng qīng sè guāng yǔ sì jù zhī pú sà wǎng hù qí guó",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 915,
   "text": "南方金刚宝菩萨摩诃萨，手持金刚摩尼，放日色光，与四俱胝菩萨往护其国。",
   "pinyin": "nán fāng jīn gāng bǎo pú sà mó hē sà shǒu chí jīn gāng mó ní fàng rì sè guāng yǔ sì jù zhī pú sà wǎng hù qí guó",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 916,
   "text": "西方金刚利菩萨摩诃萨，手持金刚剑，放金色光，与四俱胝菩萨往护其国。",
   "pinyin": "xī fāng jīn gāng lì pú sà mó hē sà shǒu chí jīn gāng jiàn fàng jīn sè guāng yǔ sì jù zhī pú sà wǎng hù qí guó",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 917,
   "text": "北方金刚药叉菩萨摩诃萨，手持金刚铃，",
   "pinyin": "běi fāng jīn gāng yào chā pú sà mó hē sà shǒu chí jīn gāng líng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 918,
   "text": "放琉璃色光，与四俱胝药叉往护其国。",
   "pinyin": "fàng liú lí sè guāng yǔ sì jù zhī yào chā wǎng hù qí guó",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 919,
   "text": "中方金刚波罗蜜多菩萨摩诃萨，手持金刚轮，",
   "pinyin": "zhōng fāng jīn gāng bō luó mì duō pú sà mó hē sà shǒu chí jīn gāng lún",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 920,
   "text": "放五色光，与四俱胝菩萨往护其国。",
   "pinyin": "fàng wǔ sè guāng yǔ sì jù zhī pú sà wǎng hù qí guó",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 921,
   "text": "是五菩萨摩诃萨，各与如是无量大众，于汝国中作大利益；",
   "pinyin": "shì wǔ pú sà mó hē sà gè yǔ rú shì wú liàng dà zhòng yú rǔ guó zhōng zuò dà lì yì",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 922,
   "text": "当立形像而供养之。",
   "pinyin": "dāng lì xíng xiàng ér gòng yǎng zhī",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 923,
   "text": "尔时，金刚手菩萨摩诃萨等，即从座起顶礼佛足，却住一面而白佛言：",
   "pinyin": "ěr shí jīn gāng shǒu pú sà mó hē sà děng jí cóng zuò qǐ dǐng lǐ fó zú què zhù yī miàn ér bái fó yán",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 924,
   "text": "世尊！",
   "pinyin": "shì zūn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 925,
   "text": "我等本愿，承佛神力，十方世界一切国土，若有此经受持、读诵、解说之处，",
   "pinyin": "wǒ děng běn yuàn chéng fó shén lì shí fāng shì jiè yí qiè guó tǔ ruò yǒu cǐ jīng shòu chí dú sòng jiě shuō zhī chù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 926,
   "text": "我当各与如是眷属，于一念顷即至其所，守护正法、建立正法，",
   "pinyin": "wǒ dāng gè yǔ rú shì juàn shǔ yú yī niàn qǐng jí zhì qí suǒ shǒu hù zhèng fǎ jiàn lì zhèng fǎ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 927,
   "text": "令其国界无诸灾难，刀兵疾疫一切皆除。",
   "pinyin": "lìng qí guó jiè wú zhū zāi nàn dāo bīng jí yì yí qiè jiē chú",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 928,
   "text": "世尊！",
   "pinyin": "shì zūn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 929,
   "text": "我有陀罗尼，能加持拥护，是一切佛本所修行速疾之门。",
   "pinyin": "wǒ yǒu tuó luó ní néng jiā chí yōng hù shì yí qiè fó běn suǒ xiū xíng sù jí zhī mén",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 930,
   "text": "若人得闻一经于耳，所有罪障悉皆消灭，",
   "pinyin": "ruò rén dé wén yī jīng yú ěr suǒ yǒu zuì zhàng xī jiē xiāo miè",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 931,
   "text": "况复诵习而令通利，以法威力，当令国界永无众难。",
   "pinyin": "kuàng fù sòng xí ér lìng tōng lì yǐ fǎ wēi lì dāng lìng guó jiè yǒng wú zhòng nàn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 932,
   "text": "即于佛前，异口同音说陀罗尼曰：",
   "pinyin": "jí yú fó qián yì kǒu tóng yīn shuō tuó luó ní yuē",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 933,
   "text": "娜谟啰怛娜怛啰夜野，",
   "pinyin": "nà mó là dá nà dá là yè yě",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 934,
   "text": "娜莫阿哩夜吠嚧者娜野，",
   "pinyin": "nà mò ā lǐ yè fèi lú zhě nà yě",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 935,
   "text": "怛他孽多夜啰诃谛，",
   "pinyin": "dá tuō niè duō yè là hē dì",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 936,
   "text": "三藐三没驮野，",
   "pinyin": "sān miǎo sān mò tuó yě",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 937,
   "text": "娜莫阿哩野，",
   "pinyin": "nà mò ā lǐ yě",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 938,
   "text": "三满多跋捺啰野，",
   "pinyin": "sān mǎn duō bá nà là yě",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 939,
   "text": "冒地萨怛嚩野，",
   "pinyin": "mào dì sà dá wā yě",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 940,
   "text": "摩诃萨怛嚩野，",
   "pinyin": "mó hē sà dá wā yě",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 941,
   "text": "摩贺迦噜抳迦野，",
   "pinyin": "mó hè jiā lū nǐ jiā yě",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 942,
   "text": "怛儞野他，",
   "pinyin": "dá nǐ yě tuō",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 943,
   "text": "枳穰娜钵啰儞闭，",
   "pinyin": "zhǐ ráng nà bō là nǐ bì",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 944,
   "text": "恶乞叉野句势，",
   "pinyin": "è qǐ chā yě jù shì",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 945,
   "text": "钵啰底婆娜嚩底，",
   "pinyin": "bō là dǐ pó nà wā dǐ",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 946,
   "text": "萨嚩没驮嚩路枳谛，",
   "pinyin": "sà wā mò tuó wā lù zhǐ dì",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 947,
   "text": "瑜誐跛哩儞澁跛宁，",
   "pinyin": "yú é bǒ lǐ nǐ sè bǒ níng",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 948,
   "text": "俨避啰努啰嚩誐系，",
   "pinyin": "yǎn bì là nǔ là wā é xì",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 949,
   "text": "底哩野特嚩，",
   "pinyin": "dǐ lǐ yě tè wā",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 950,
   "text": "跛哩儞澁跛宁，",
   "pinyin": "bǒ lǐ nǐ sè bǒ níng",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 951,
   "text": "冒地质多散惹娜儞，",
   "pinyin": "mào dì zhì duō sàn rě nà nǐ",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 952,
   "text": "萨嚩毘晒迦毘色讫谛，",
   "pinyin": "sà wā pí shài jiā pí sè qì dì",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 953,
   "text": "达磨娑誐啰三步谛，",
   "pinyin": "dá mó suō é là sān bù dì",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 954,
   "text": "阿慕伽室啰嚩儜，",
   "pinyin": "ā mù qié shì là wā níng",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 955,
   "text": "摩贺三满多跋捺啰步弥，",
   "pinyin": "mó hè sān mǎn duō bá nà là bù mí",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 956,
   "text": "涅哩野谛，",
   "pinyin": "niè lǐ yě dì",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 957,
   "text": "尾野羯啰拏，",
   "pinyin": "wěi yě jié là ná",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 958,
   "text": "跛哩钵啰跛儞，",
   "pinyin": "bǒ lǐ bō là bǒ nǐ",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 959,
   "text": "萨嚩悉驮，",
   "pinyin": "sà wā xī tuó",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 960,
   "text": "娜么塞讫哩谛，",
   "pinyin": "nà mó sāi qì lǐ dì",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 961,
   "text": "萨嚩冒地萨怛嚩，",
   "pinyin": "sà wā mào dì sà dá wā",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 962,
   "text": "散惹娜儞，",
   "pinyin": "sàn rě nà nǐ",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 963,
   "text": "婆誐嚩底，",
   "pinyin": "pó é wā dǐ",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 964,
   "text": "没驮么谛，",
   "pinyin": "mò tuó mó dì",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 965,
   "text": "阿啰儞迦啰嬭，",
   "pinyin": "ā là nǐ jiā là nǎi",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 966,
   "text": "阿啰拏迦啰嬭，",
   "pinyin": "ā là ná jiā là nǎi",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 967,
   "text": "摩贺钵啰枳穰，",
   "pinyin": "mó hè bō là zhǐ ráng",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 968,
   "text": "播啰弭谛娑嚩贺。",
   "pinyin": "bō là mǐ dì suō wā hè",
   "part": "咒语",
   "heading": "陀罗尼"
  },
  {
   "n": 969,
   "text": "尔时，世尊闻是说已，赞金刚手等诸菩萨言：",
   "pinyin": "ěr shí shì zūn wén shì shuō yǐ zàn jīn gāng shǒu děng zhū pú sà yán",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 970,
   "text": "善哉，善哉！",
   "pinyin": "shàn zāi shàn zāi",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 971,
   "text": "若有诵持此陀罗尼者，我及十方诸佛悉常加护，",
   "pinyin": "ruò yǒu sòng chí cǐ tuó luó ní zhě wǒ jí shí fāng zhū fó xī cháng jiā hù",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 972,
   "text": "诸恶神鬼敬之如佛，不久当得阿耨多罗三藐三菩提。",
   "pinyin": "zhū è shén guǐ jìng zhī rú fó bù jiǔ dāng dé ā nòu duō luó sān miǎo sān pú tí",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 973,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 974,
   "text": "吾以此经付嘱汝等：",
   "pinyin": "wú yǐ cǐ jīng fù zhǔ rǔ děng",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 975,
   "text": "毘舍离国、憍萨罗国、室罗筏国、摩伽陀国、波罗痆斯国、",
   "pinyin": "pí shě lí guó jiāo sà luó guó shì luó fá guó mó qié tuó guó bō luó niè sī guó",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 976,
   "text": "迦毘罗国、拘尸那国、憍睒弥国、般遮罗国、波咤罗国、末土罗国、",
   "pinyin": "jiā pí luó guó jū shī nà guó jiāo shǎn mí guó bō zhē luó guó bō zhà luó guó mò tǔ luó guó",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 977,
   "text": "乌尸尼国、奔咤䟦多国、提婆䟦多国、迦尸国瞻波国，",
   "pinyin": "wū shī ní guó bēn zhà bá duō guó tí pó bá duō guó jiā shī guó zhān bō guó",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 978,
   "text": "如是一切诸国王等，皆应受持般若波罗蜜多。",
   "pinyin": "rú shì yí qiè zhū guó wáng děng jiē yīng shòu chí bō rě bō luó mì duō",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 979,
   "text": "时诸大众、阿修罗等，闻佛所说诸灾难事，身毛皆竖，高声唱言：",
   "pinyin": "shí zhū dà zhòng ā xiū luó děng wén fó suǒ shuō zhū zāi nàn shì shēn máo jiē shù gāo shēng chàng yán",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 980,
   "text": "愿我未来不生彼国。",
   "pinyin": "yuàn wǒ wèi lái bù shēng bǐ guó",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 981,
   "text": "时十六王，即舍王位修出家道，具八胜处、十一切处，得伏忍、信忍、无生法忍。",
   "pinyin": "shí shí liù wáng jí shě wáng wèi xiū chū jiā dào jù bā shèng chù shí yí qiè chù dé fú rěn xìn rěn wú shēng fǎ rěn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 982,
   "text": "尔时，一切天人大众、阿修罗等，散曼陀罗花、曼殊沙花、婆师迦花、苏曼那花，",
   "pinyin": "ěr shí yí qiè tiān rén dà zhòng ā xiū luó děng sàn màn tuó luó huā màn shū shā huā pó shī jiā huā sū màn nà huā",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 983,
   "text": "以供养佛，随其种性得三脱门、生空、法空、菩提分法。",
   "pinyin": "yǐ gòng yǎng fó suí qí zhǒng xìng dé sān tuō mén shēng kōng fǎ kōng pú tí fēn fǎ",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 984,
   "text": "无量无数菩萨摩诃萨，散拘勿头花、波头摩花而供养佛，",
   "pinyin": "wú liàng wú shù pú sà mó hē sà sàn jū wù tóu huā bō tóu mó huā ér gòng yǎng fó",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 985,
   "text": "无量三昧悉皆现前，得住顺忍、无生法忍。",
   "pinyin": "wú liàng sān mèi xī jiē xiàn qián dé zhù shùn rěn wú shēng fǎ rěn",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 986,
   "text": "无量无数菩萨摩诃萨，得恒河沙诸三昧门，真俗平等，具无碍解，",
   "pinyin": "wú liàng wú shù pú sà mó hē sà dé héng hé shā zhū sān mèi mén zhēn sú píng děng jù wú ài jiě",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 987,
   "text": "常起大悲，于百万亿阿僧祇佛刹微尘数世界，广利众生，现身成佛。",
   "pinyin": "cháng qǐ dà bēi yú bǎi wàn yì ā sēng qí fó chà wēi chén shù shì jiè guǎng lì zhòng shēng xiàn shēn chéng fó",
   "part": "长行",
   "heading": "奉持品第七"
  },
  {
   "n": 988,
   "text": "佛告波斯匿王：",
   "pinyin": "fó gào bō sī nì wáng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 989,
   "text": "今诫汝等！",
   "pinyin": "jīn jiè rǔ děng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 990,
   "text": "吾灭度后，正法欲灭，后五十年、后五百年、后五千年，无佛、法、僧。",
   "pinyin": "wú miè dù hòu zhèng fǎ yù miè hòu wǔ shí nián hòu wǔ bǎi nián hòu wǔ qiān nián wú fó fǎ sēng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 991,
   "text": "此经、三宝，付诸国王建立守护，令我四部诸弟子等，受持、读诵，",
   "pinyin": "cǐ jīng sān bǎo fù zhū guó wáng jiàn lì shǒu hù lìng wǒ sì bù zhū dì zǐ děng shòu chí dú sòng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 992,
   "text": "解其义理，广为众生宣说法要，令其修习出离生死。",
   "pinyin": "jiě qí yì lǐ guǎng wéi zhòng shēng xuān shuō fǎ yào lìng qí xiū xí chū lí shēng sǐ",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 993,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 994,
   "text": "后五浊世，一切国王、王子、大臣自恃高贵，破灭吾教，明作制法，制我弟子。",
   "pinyin": "hòu wǔ zhuó shì yí qiè guó wáng wáng zǐ dà chén zì shì gāo guì pò miè wú jiào míng zuò zhì fǎ zhì wǒ dì zǐ",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 995,
   "text": "比丘、比丘尼不听出家修行正道，亦复不听造佛塔像。",
   "pinyin": "bǐ qiū bǐ qiū ní bù tīng chū jiā xiū xíng zhèng dào yì fù bù tīng zào fó tǎ xiàng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 996,
   "text": "白衣高座，比丘地立，与兵奴法等无有异。",
   "pinyin": "bái yī gāo zuò bǐ qiū dì lì yǔ bīng nú fǎ děng wú yǒu yì",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 997,
   "text": "当知尔时，法灭不久。",
   "pinyin": "dāng zhī ěr shí fǎ miè bù jiǔ",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 998,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 999,
   "text": "破国因缘，皆汝自作。",
   "pinyin": "pò guó yīn yuán jiē rǔ zì zuò",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1000,
   "text": "恃己威力，制四部众，不听修福。",
   "pinyin": "shì jǐ wēi lì zhì sì bù zhòng bù tīng xiū fú",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1001,
   "text": "诸恶比丘受别请法。",
   "pinyin": "zhū è bǐ qiū shòu bié qǐng fǎ",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1002,
   "text": "知识比丘共为一心，互相亲善，斋会求福。",
   "pinyin": "zhī shí bǐ qiū gòng wéi yī xīn hù xiāng qīn shàn zhāi huì qiú fú",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1003,
   "text": "是外道法，都非我教。",
   "pinyin": "shì wài dào fǎ dōu fēi wǒ jiào",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1004,
   "text": "百姓疾疫，无量苦难。",
   "pinyin": "bǎi xìng jí yì wú liàng kǔ nàn",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1005,
   "text": "当知尔时国土破灭。",
   "pinyin": "dāng zhī ěr shí guó tǔ pò miè",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1006,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1007,
   "text": "法末世时，国王、大臣、四部弟子，各作非法，",
   "pinyin": "fǎ mò shì shí guó wáng dà chén sì bù dì zǐ gè zuò fēi fǎ",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1008,
   "text": "横与佛教作诸过咎，非法非律系缚比丘，如彼狱囚。",
   "pinyin": "héng yǔ fó jiào zuò zhū guò jiù fēi fǎ fēi lǜ xì fù bǐ qiū rú bǐ yù qiú",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1009,
   "text": "当知尔时，法灭不久。",
   "pinyin": "dāng zhī ěr shí fǎ miè bù jiǔ",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1010,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1011,
   "text": "我灭度后，四部弟子，一切国王、王子、百官，乃是任持护三宝者，",
   "pinyin": "wǒ miè dù hòu sì bù dì zǐ yí qiè guó wáng wáng zǐ bǎi guān nǎi shì rèn chí hù sān bǎo zhě",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1012,
   "text": "而自破灭，如师子身中虫，自食师子肉，非外道也。",
   "pinyin": "ér zì pò miè rú shī zǐ shēn zhōng chóng zì shí shī zǐ ròu fēi wài dào yě",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1013,
   "text": "坏我法者得大过咎——正法衰薄，民无正行，诸恶渐增，其寿日减，无复孝子，",
   "pinyin": "huài wǒ fǎ zhě dé dà guò jiù zhèng fǎ shuāi bó mín wú zhèng xíng zhū è jiàn zēng qí shòu rì jiǎn wú fù xiào zǐ",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1014,
   "text": "六亲不和，天龙不祐，恶鬼恶龙日来侵害，灾怪相继为祸纵横，",
   "pinyin": "liù qīn bù hé tiān lóng bù yòu è guǐ è lóng rì lái qīn hài zāi guài xiāng jì wéi huò zòng héng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1015,
   "text": "当堕地狱、傍生、饿鬼，若得为人，贫穷下贱诸根不具——如影随形、如响应声，",
   "pinyin": "dāng duò dì yù bàng shēng è guǐ ruò dé wéi rén pín qióng xià jiàn zhū gēn bù jù rú yǐng suí xíng rú xiǎng yìng shēng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1016,
   "text": "如人夜书，火灭字存，毁法果报亦复如是。",
   "pinyin": "rú rén yè shū huǒ miè zì cún huǐ fǎ guǒ bào yì fù rú shì",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1017,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1018,
   "text": "未来世中，一切国王、王子、大臣，与我弟子横立记籍，",
   "pinyin": "wèi lái shì zhōng yí qiè guó wáng wáng zǐ dà chén yǔ wǒ dì zǐ héng lì jì jí",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1019,
   "text": "设官典主大小僧统，非理役使。",
   "pinyin": "shè guān diǎn zhǔ dà xiǎo sēng tǒng fēi lǐ yì shǐ",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1020,
   "text": "当知尔时，佛法不久。",
   "pinyin": "dāng zhī ěr shí fó fǎ bù jiǔ",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1021,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1022,
   "text": "未来世中，一切国王、四部弟子，当依十方一切诸佛常所行道，建立流通。",
   "pinyin": "wèi lái shì zhōng yí qiè guó wáng sì bù dì zǐ dāng yī shí fāng yí qiè zhū fó cháng suǒ xíng dào jiàn lì liú tōng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1023,
   "text": "而恶比丘为求名利，不依我法，于国王前自说过患，作破法缘。",
   "pinyin": "ér è bǐ qiū wéi qiú míng lì bù yī wǒ fǎ yú guó wáng qián zì shuō guò huàn zuò pò fǎ yuán",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1024,
   "text": "其王不别，信受此语，横立制法，不依佛戒。",
   "pinyin": "qí wáng bù bié xìn shòu cǐ yǔ héng lì zhì fǎ bù yī fó jiè",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1025,
   "text": "当知尔时，法灭不久。",
   "pinyin": "dāng zhī ěr shí fǎ miè bù jiǔ",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1026,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1027,
   "text": "未来世中，国王、大臣、四部弟子，自作破法、破国因缘，身自受之，非佛法咎。",
   "pinyin": "wèi lái shì zhōng guó wáng dà chén sì bù dì zǐ zì zuò pò fǎ pò guó yīn yuán shēn zì shòu zhī fēi fó fǎ jiù",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1028,
   "text": "天龙舍去，五浊转增，若具说者穷劫不尽。",
   "pinyin": "tiān lóng shě qù wǔ zhuó zhuǎn zēng ruò jù shuō zhě qióng jié bù jìn",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1029,
   "text": "尔时，十六大国王闻说未来如是诸诫，",
   "pinyin": "ěr shí shí liù dà guó wáng wén shuō wèi lái rú shì zhū jiè",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1030,
   "text": "悲啼号泣，声动三千，天地昏暗，光明不现。",
   "pinyin": "bēi tí hào qì shēng dòng sān qiān tiān dì hūn àn guāng míng bù xiàn",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1031,
   "text": "时诸王等，各各至心受持佛语，不制四部出家学道，当如佛教。",
   "pinyin": "shí zhū wáng děng gè gè zhì xīn shòu chí fó yǔ bù zhì sì bù chū jiā xué dào dāng rú fó jiào",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1032,
   "text": "尔时，恒河沙等无量大众皆共叹言：",
   "pinyin": "ěr shí héng hé shā děng wú liàng dà zhòng jiē gòng tàn yán",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1033,
   "text": "当尔之时，世间空虚是无佛世。",
   "pinyin": "dāng ěr zhī shí shì jiān kōng xū shì wú fó shì",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1034,
   "text": "尔时，波斯匿王白佛言：",
   "pinyin": "ěr shí bō sī nì wáng bái fó yán",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1035,
   "text": "世尊！",
   "pinyin": "shì zūn",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1036,
   "text": "当何名此经？",
   "pinyin": "dāng hé míng cǐ jīng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1037,
   "text": "我等云何奉持？",
   "pinyin": "wǒ děng yún hé fèng chí",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1038,
   "text": "佛告大王：",
   "pinyin": "fó gào dà wáng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1039,
   "text": "此经名为仁王护国般若波罗蜜多，亦得名为甘露法药，若有服行能愈诸疾。",
   "pinyin": "cǐ jīng míng wéi rén wáng hù guó bō rě bō luó mì duō yì dé míng wéi gān lù fǎ yào ruò yǒu fú xíng néng yù zhū jí",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1040,
   "text": "大王！",
   "pinyin": "dà wáng",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1041,
   "text": "般若波罗蜜多所有功德，犹如虚空不可测量，若有受持、读诵之者，",
   "pinyin": "bō rě bō luó mì duō suǒ yǒu gōng dé yóu rú xū kōng bù kě cè liàng ruò yǒu shòu chí dú sòng zhī zhě",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1042,
   "text": "所获功德，能护仁王及诸众生，犹如垣墙，亦如城壁，是故汝等应当受持。",
   "pinyin": "suǒ huò gōng dé néng hù rén wáng jí zhū zhòng shēng yóu rú yuán qiáng yì rú chéng bì shì gù rǔ děng yīng dāng shòu chí",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1043,
   "text": "佛说是经已，弥勒、师子吼等无量菩萨摩诃萨，舍利弗、须菩提等无量声闻，",
   "pinyin": "fó shuō shì jīng yǐ mí lè shī zǐ hǒu děng wú liàng pú sà mó hē sà shè lì fú xū pú tí děng wú liàng shēng wén",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1044,
   "text": "欲界、色界无量天人，比丘、比丘尼、优婆塞、优婆夷，",
   "pinyin": "yù jiè sè jiè wú liàng tiān rén bǐ qiū bǐ qiū ní yōu pó sāi yōu pó yí",
   "part": "长行",
   "heading": "嘱累品第八"
  },
  {
   "n": 1045,
   "text": "阿修罗等，一切大众，闻佛所说，皆大欢喜，信受奉行。",
   "pinyin": "ā xiū luó děng yí qiè dà zhòng wén fó suǒ shuō jiē dà huān xǐ xìn shòu fèng xíng",
   "part": "长行",
   "heading": "嘱累品第八"
  }
 ]
}
